        public int Age(string ageTyp)
        {
            if (_ageNbr != 0)
            {
                string t = "";
                switch (ageTyp.ToUpper() ?? "")
                {
                    case "Y":
                    case "YEAR":
                        {
                            t = "Y";
                            break;
                        }
                    case "M":
                    case "MONTH":
                        {
                            t = "M";
                            break;
                        }
                    case "W":
                    case "WEEK":
                        {
                            t = "W";
                            break;
                        }
                    case "D":
                    case "DAY":
                        {
                            t = "D";
                            break;
                        }
                }
                if ((_ageType ?? "") == (t ?? ""))
                    return _ageNbr;
            }

            return General.CalcAge(_dob, ageTyp, CalcDobFromDate);
        }

