        public void FilterCorrectedTestResults()
        {
            var list = new List<string>();
            ReportAnalyte analyte;
            foreach (string key in CorrectedTests.Keys)
            {
                analyte = FindAnalyte(key, true);
                if (analyte.TransmitStatus != transmitStatusType.Released && analyte.ResultStatusBeforeRuleRun != resultStatusType.Corrected)
                {
                    list.Add(key);
                }
            }

            foreach (string key in list)
                CorrectedTests.Remove(key);

        }

        /// <summary>
        /// To split the values and build the objects for inserting into ExternalCalcLabQueue table. Prior to adding an entry into these objects, 
        /// we need to confirm that there isn’t already an entry  for the same LabId and CalculationName.  If there is, just bypass.  We will 
        /// only need one row.
        /// </summary>
        /// <param name="inbound">String (comma separated values containing LabId and CalculationName.  i.e. “1,FT”)</param>
        /// <remarks></remarks>
        public void RouteToLabForCalculation(string inbound)
        {
            var regex = new Regex("^[0-9]+,[a-zA-Z0-9 ]+$");
            if (!regex.IsMatch(inbound))
            {
                // Error in inbound parameter
                throw new ArgumentException("Invalid inbound parameter. Wrong format.");
            }
            string[] array = inbound.Split(",".ToCharArray());
            int labId = int.Parse(array[0]);
            string calculationName = array[1];
            if (calculationName.ToLower().Equals("4k"))
                return;

            if (_externalCalcLabQueue is null)
            {
                _externalCalcLabQueue = ExternalCalcLabQueue.CreateExternalCalcLabQueue(labId, calculationName);
                _externalCalcLabQueue.ReportId = _id;
                _externalCalcLabQueue.UserName = "unknown";
                if (CurrentUser is not null)
                {
                    _externalCalcLabQueue.UserName = CurrentUser.Name;
                }
            }
        }

        public void Release4KPanel(string pnl)
        {
            string[] testCodes = Configuration.B24KSettings.GetString("4K_panel_code").Split(',');
            foreach (string tst in testCodes)
            {
                var analytePanel = FindAnalytePanel(tst);
                if (analytePanel is not null)
                {
                    analytePanel.MarkAsReleased();
                    return;
                }
            }
        }

        public void PerformCalculation(string calculationName)
        {
            switch (calculationName.ToLower() ?? "")
            {
                case "4k":
                    {
                        var recalcBypass = Configuration.LISSettings.GetList("B24KRecalcBypass");
                        if (AccessionNbr.Trim().Length == 9 && recalcBypass.Contains(AccessionNbr.Substring(0, 2)))
                        {
                            return;
                        }
                        if (CurrentUser is not null)
                        {
                            CalculateHGCancerRisk(CurrentUser.Name);
                        }
                        else
                        {
                            CalculateHGCancerRisk("unknown");
                        }

                        break;
                    }

                default:
                    {
                        break;
                    }
            }
        }

        public bool SetAnalyteSpecimenCodes(string testCode, string specimenCodes)
        {
            bool flag = false;
            ReportAnalyte a;
            ReportAnalytePanel p;
            a = FindAnalyte(testCode, false);
            if (a is not null)
            {
                Log.Debug($"Found Analyte:{a.Code}, Specimens:{specimenCodes}");
                a.SpecimenCodes = specimenCodes;
                Log.Debug($"--> Analyte:{a.Code}, Specimens:{a.SpecimenCodes}");
                flag = true;
            }
            else
            {
                p = FindAnalytePanel(testCode);
                if (p is not null)
                {
                    Log.Debug($"Found Panel:{p.PanelCode}, Specimens:{specimenCodes}");
                    p.SetAnalyteSpecimenCodes(specimenCodes);
                    flag = true;
                }
            }
            return flag;
        }

