                _reportId = _report.ID;
                _accessionNumber = _report.AccessionNbr;
                _order = OrderManager.FetchOrder(_report.OrderId);
                _panelCodes.AddRange(Configuration.B24KSettings.GetString("4K_panel_code").Split(comma));
                _serumPanels.AddRange(Configuration.B24KSettings.GetString("4K_panel_serum").Split(comma));
                _plasmaPanels.AddRange(Configuration.B24KSettings.GetString("4K_panel_plasma").Split(comma));
            }

            #region Public Properties

            public bool Fetch4KPanel()
            {

                while (_panelCodes.Count > 0)
                {
                    string pCode = _panelCodes[0];
                    _panel = _report.FindAnalytePanel(pCode);
                    _panelCodes.RemoveAt(0);
                    if (_panel is not null && (_panel.SPMStatus == SPMStatusValue.None || _panel.SPMStatus == SPMStatusValue.Reversed))
                    {
                        return true;
                    }
                }
                return false;

            }

