            {
                get
                {
                    if (_serumPanels.Contains(_panel.PanelCode))
                    {
                        _sampleType = FourKSampleType.Serum;
                        return _sampleType;
                    }
                    if (_plasmaPanels.Contains(_panel.PanelCode))
                    {
                        _sampleType = FourKSampleType.Plasma;
                        return _sampleType;
                    }
                    throw new Exception("Unknown sample type.");
                }
            }

