            public bool SetB24KResult(string fourKScoreresult, string userName, string serialNumber = "")
            {
                bool allDataOk = true;
                if (_sampleType == FourKSampleType.Serum)
                {
                    allDataOk = SetB2Result(Configuration.B24KSettings.GetString("4k_serum"), fourKScoreresult, "4K Score", userName, serialNumber);
                }
