            public static bool ValidateAndClearInequality(string value, ref decimal numericResult)
            {
                char[] signs = new char[] { '>', '<', '=' };
                return decimal.TryParse(Remove(value, signs), out numericResult);
            }

            public static string Remove(string s, IEnumerable<char> chars)
            {
                return new string(s.Where(c => !chars.Contains(c)).ToArray());
            }

            #endregion

            #region Private methods

            private bool SetB2Result(string testCode, string testResult, string runTestCode, string userName, string serialNumber = "")
            {
                bool allDataOk = true;
                string exceptionMessage = "Report {0} does not have test code {1} for {2} test.";
                string logMessage = "Set Result Failed -- Original Result:{0} New Result {1}";
                bool analyteFound = false;

                string[] testCodes = testCode.Split(comma);
                foreach (string tst in testCodes)
                {
                    var rptAnalyte = _report.FindAnalyte(tst, true);
                    if (rptAnalyte is not null)
                    {
                        analyteFound = true;
                        if (rptAnalyte.ResultValue.Equals("") || _allowOverwrite)
                        {
                            rptAnalyte.InstrumentId = serialNumber;
                            rptAnalyte.SetResultValue(testResult, true);
                        }
                        else
                        {
                            allDataOk = false;
                        }
                        break;
                    }
                }
                if (analyteFound == false)
                {
                    allDataOk = false;
                }
                return allDataOk;
            }

            private string Get4kComponentResultValue(string testCode)
            {
                if (_report is null)
                    return "";
                string[] testCodes = testCode.Split(comma);
                foreach (string test in testCodes)
                {
                    var analyteList = _report.FindAll(test, true, true);
                    if (analyteList.Count == 1)
                    {
                        return analyteList[0].ResultValue;
                    }
                    else if (analyteList.Count > 1)
                    {
                        return string.Empty;
                    }
                }
                return string.Empty;
            }

            private int Get4kComponentResultCount(string testCode)
            {
                if (_report is null)
                    return 0;
                string[] testCodes = testCode.Split(comma);
                int sum = 0;
                foreach (string test in testCodes)
                    sum += _report.FindAll(test, true, true).Count;
                return sum;
            }

            private Enums.PriorBiopsyType GetPriorBiopsyResult()
            {

                if (_report is null)
                {
                    return Enums.PriorBiopsyType.Missing;
                }

                var a = _report.FindAnalyte(Configuration.B24KSettings.GetString("prior_biopsy_code"), true);

                if (a is null || a.ResultValue.IsNothingOrEmpty())
                {
                    return Enums.PriorBiopsyType.Missing;    // no information about biopsy
                }

                if (Configuration.LISSettings.GetList("FourK_Biopsy_Missing").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.PriorBiopsyType.Missing;    // no information about biopsy
                }

                if (Configuration.LISSettings.GetList("FourK_Biopsy_Negative").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.PriorBiopsyType.Negative;   // biopsy results were negative
                }

                if (Configuration.LISSettings.GetList("FourK_Biopsy_Positive").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.PriorBiopsyType.Positive;   // biopsy results were positive (we should not get here)
                }

                if (Configuration.LISSettings.GetList("FourK_Biopsy_None").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.PriorBiopsyType.NoPriorBiopsy;  // no prior biopsy was done
                }

                return Enums.PriorBiopsyType.Missing;

            }

            private Enums.DreResultType GetDreResult()
            {

                if (_report is null)
                {
                    return Enums.DreResultType.Missing;
                }

                var a = _report.FindAnalyte(Configuration.B24KSettings.GetString("dre_results_code"), true);

                _dreResultText = a.ResultValue;
                _dreUnavailable = a.ResultValue.Equals("Unavailable", StringComparison.InvariantCultureIgnoreCase);
                _dreNotProvided = a.ResultValue.Equals("Not Provided", StringComparison.InvariantCultureIgnoreCase);
                _dreNotPerformed = a.ResultValue.Equals("Not Performed", StringComparison.InvariantCultureIgnoreCase);

                if (a is null || a.ResultValue.IsNothingOrEmpty())
                {
                    return Enums.DreResultType.Missing;
                }

                if (Configuration.LISSettings.GetList("FourK_DRE_Nodule").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.DreResultType.Nodule;
                }

                if (Configuration.LISSettings.GetList("FourK_DRE_NoNodule").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.DreResultType.NoNodule;
                }

                if (Configuration.LISSettings.GetList("FourK_DRE_NoInfo").Contains(a.ResultValue, new CompareText()))
                {
                    return Enums.DreResultType.NoInfo;
                }

                return Enums.DreResultType.Missing;

            }

            #endregion

        }

        public Dictionary<string, string> GetRequiredInstrumentAnalytes()
        {
            var dcitanalytes = new Dictionary<string, string>();

            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.CanEnableInstrument() && string.IsNullOrEmpty(a.InstrumentId))
                {
                    dcitanalytes.Add(a.Code, a.AnalyteName);
                }
            }

            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {

                foreach (ReportAnalyte a in p.Analytes.List)
                {
                    if (a.CanEnableInstrument() && string.IsNullOrEmpty(a.InstrumentId))
                    {
                        dcitanalytes.Add(a.Code, a.AnalyteName);
                    }
                }
            }

            return dcitanalytes;
        }

        public void CalculateHGCancerRisk(string userName)
        {
            var sb = new StringBuilder();
            decimal age = 0.0m;
            DateTime dateOfBirth;
            DateTime dateOfCollection;
            decimal freePSA = 0.0m;
            decimal totalPSA = 0.0m;
            decimal intactPSA = 0.0m;
            decimal hk2 = 0.0m;
            Enums.DreResultType dre;
            string dreResult;
            Enums.PriorBiopsyType priorBiopsy;
            bool priorNegativeBiopsy;
            string message;
            var sampleType = FourKSampleType.None;
            B24KAccessionInfo accessionInfo = null;

            try
            {

                if (ID == 0L)
                {
                    message = "Bypassing calculation: ReportId = 0. ";
                    sb.Append(message);
                    AuditManager.LogCustomObjectAction(this, message);
                    return;
                }

                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
                string token = Configuration.LISSettings.GetString("B24KToken");
                var proxyCalculator = new CalculatorProxy(token);

                if (accessionInfo == null)
                {
                    accessionInfo = new B24KAccessionInfo(this, true);
                }

                if (!DateTime.TryParse(accessionInfo.CollectionDate, out dateOfCollection))
                {
                    message = $"Bypassing 4K calculation: Date of Collection '{accessionInfo.CollectionDate}' not valid. ";
                    sb.Append(message);
                    AuditManager.LogCustomObjectAction(this, message);
                    return;
                }
                sb.Append(string.Format("DOC: '{0}'. ", dateOfCollection));

                while (accessionInfo.Fetch4KPanel())
                {

                    // If the component values for 4K are not yet ready, no calculation is done.

                    bool clinicalTrial = Configuration.LISSettings.GetString("FourK_Panel_OverrideValidation").Contains(accessionInfo.PanelCode, StringComparison.InvariantCultureIgnoreCase);

                    sampleType = accessionInfo.BloodSampleType; // "SERUM" Or "PLASMA"
                    sb.Append(string.Format("Sample Type: '{0}'. ", sampleType));

                    // If multiple tPSA/fPSA values exist, abort the calculation with an alert email.
                    if (accessionInfo.TotalPsaResultCount > 1 | accessionInfo.FreePsaResultCount > 1)
                    {
                        message = "Bypassing 4K calculation: Multiple tPSA/fPSA values exist. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(ID.ToString(), "Bioreference.LIS.Report", message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        throw new FourKCalculationException(sb.ToString());
                    }

                    if (!B24KAccessionInfo.ValidateAndClearInequality(accessionInfo.FreePsaValue, ref freePSA))
                    {
                        message = $"Bypassing 4K calculation: FreePSA Value '{accessionInfo.FreePsaValue}' not numeric. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(this, message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        continue;
                    }
                    sb.Append(string.Format("freePSA: '{0}'. ", freePSA));

                    if (!B24KAccessionInfo.ValidateAndClearInequality(accessionInfo.TotalPsaValue, ref totalPSA))
                    {
                        message = $"Bypassing 4K calculation: TotalPSA Value '{accessionInfo.TotalPsaValue}' not numeric. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(this, message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        continue;
                    }
                    sb.Append(string.Format("totalPSA: '{0}'. ", totalPSA));

                    if (!B24KAccessionInfo.ValidateAndClearInequality(accessionInfo.IpsaValue, ref intactPSA))
                    {
                        message = $"Bypassing 4K calculation: IPSA Value '{accessionInfo.IpsaValue}' not numeric. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(this, message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        continue;
                    }
                    sb.Append(string.Format("intactPSA '{0}'. ", intactPSA));

                    if (!B24KAccessionInfo.ValidateAndClearInequality(accessionInfo.Hk2Value, ref hk2))
                    {
                        message = $"Bypassing 4K calculation: HK2 Value '{accessionInfo.Hk2Value}' not numeric. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(this, message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        continue;
                    }
                    sb.Append(string.Format("hk2 '{0}'. ", hk2));

                    // If the DOB or AOE values are not valid, abort the calculation with an alert email.

                    if (!DateTime.TryParse(accessionInfo.DateOfBirth, out dateOfBirth))
                    {
                        message = $"Bypassing 4K calculation: Date of Birth '{accessionInfo.DateOfBirth}' not valid. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(ID.ToString(), "Bioreference.LIS.Report", message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        throw new FourKCalculationException(sb.ToString());
                    }
                    sb.Append(string.Format("DOB: '{0}'. ", dateOfBirth));

                    age = (decimal)(dateOfCollection.Subtract(dateOfBirth).TotalDays / 365.25);

                    if (age < Configuration.LISSettings.GetInt("FourK_Minimum_Age") && !clinicalTrial)
                    {
                        message = $"Bypassing 4K calculation: Age '{age:#.0000}' below minimum of {Configuration.LISSettings.GetInt("FourK_Minimum_Age")}. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(ID.ToString(), "Bioreference.LIS.Report", message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        throw new FourKCalculationException(sb.ToString());
                    }
                    sb.Append($"Age: '{age:#.00}'. ");

                    dre = accessionInfo.DreResultValue;
                    string dreResultText = accessionInfo.DreResultText;
                    bool validDre = false;

                    if (dre == Enums.DreResultType.NoNodule || dre == Enums.DreResultType.Nodule)
                    {
                        //Nodule and No NoNodule are always valid
                        validDre = true;
                    }
                    else if (dre == Enums.DreResultType.Missing)
                    {
                        // unknown dre value is never valid
                        validDre = false;
                    }
                    else if (dre == Enums.DreResultType.NoInfo)
                    {
                        // NoInfo could be derived from 'Not Performed', 'Not Provided', or 'Unavailable'.
                        // Special rules apply based on clinical trial and actual dre text.
                        if (dreResultText.CompareText("Not Performed"))
                            validDre = false;
                        else if (dreResultText.CompareText("Not Provided") && !clinicalTrial)
                            validDre = false;
                        else if (dreResultText.CompareText("Not Provided") && clinicalTrial)
                            validDre = true;
                        else if (dreResultText.CompareText("Unavailable"))
                            validDre = true;
                    }

                    if (!validDre)
                    {
                        message = $"Bypassing 4K calculation: DRE value '{dre}' missing. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(this, message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        throw new FourKCalculationException(sb.ToString());
                    }
                    dreResult = dre.ToString();
                    sb.Append(string.Format("DreResultValue: '{0}'. ", dreResult));

                    priorBiopsy = accessionInfo.PriorBiopsyResultValue;
                    if (priorBiopsy == Enums.PriorBiopsyType.Missing && !clinicalTrial)
                    {
                        message = $"Bypassing 4K calculation: Prior Biopsy value '{priorBiopsy}' missing. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(this, message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        throw new FourKCalculationException(sb.ToString());
                    }
                    if (priorBiopsy == Enums.PriorBiopsyType.Positive && !clinicalTrial)
                    {
                        message = "Bypassing 4K calculation: Positive Prior Biopsy. ";
                        sb.Append(message);
                        AuditManager.LogCustomObjectAction(ID.ToString(), "Bioreference.LIS.Report", message);
                        accessionInfo.SetB24KResult(string.Empty, userName);
                        throw new FourKCalculationException(sb.ToString());
                    }
                    switch (priorBiopsy)
                    {
                        case Enums.PriorBiopsyType.Negative:
                            {
                                sb.Append("Negative Prior Biopsy. ");
                                break;
                            }
                        case Enums.PriorBiopsyType.Positive:
                            {
                                sb.Append("Positive Prior Biopsy. ");
                                break;
                            }
                        case Enums.PriorBiopsyType.NoPriorBiopsy:
                            {
                                sb.Append("No Prior Biopsy. ");
                                break;
                            }
                    }
                    priorNegativeBiopsy = priorBiopsy == Enums.PriorBiopsyType.Negative;

                    // Call external web service and populate result value.
                    string sample = sampleType.ToString().ToUpper();
                    double Result = 100.0d * proxyCalculator.CalculateHGCancerRisk(sample, age, freePSA, totalPSA, intactPSA, hk2, dreResult, priorNegativeBiopsy);
                    bool flag = accessionInfo.SetB24KResult(Result.ToString(), userName);
                    message = flag ? "4K Score Calculated" : "4K Score Calculation Failed";
                    AuditManager.LogCustomObjectAction(this, message);
                    sb.Append(string.Format("4K Result: '{0}'. ", Result));

                }
            }

            catch (FourKCalculationException ex)
            {
                fail4KMessage = ex.Message;
                fail4K = true;
            }
            catch (Exception ex)
            {
                Log.Error($"{sb}: {ex.Message}", ex);
                throw new Exception(sb.ToString() + " Error message:" + ex.Message, ex);
            }
            finally
            {
                Log.Debug(sb.ToString());
            }


        }

