        private void PriorResultsFetch()
        {

            try
            {
                var analyteList = new List<string>();
                foreach (ReportAnalyte a in _orderAnalytes.List)
                {
                    if (!analyteList.Contains(a.Code))
                        analyteList.Add(a.Code);
                }
                foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
                {
                    foreach (ReportAnalyte a in p.Analytes.List)
                    {
                        if (!analyteList.Contains(a.Code))
                            analyteList.Add(a.Code);
                    }
                }
                var results = LIS.PriorResults.Fetch((int)_id, string.Join(",", analyteList), false, false);
                _priorResultList = new List<PriorResult>();
                foreach (PriorResult result in results.List)
                {
                    // don't load result if it's from the current report or if it already exists in our list.
                    if (result.ReportId == _id || (from pr in _priorResultList
                                                   where string.Compare(pr.AnalyteCode, result.AnalyteCode, true) == 0
                                                   select pr.AnalyteCode).Any())
                    {
                        continue;
                    }
                    // don't load the result if it was released after the corresponding analyte in the current report, we want prior ones.
                    var ra = FindAnalyte(result.AnalyteCode, true);
                    if (ra is not null && ra.ReleaseDate > DateTime.Parse("1900-01-01") && (ra.ReleaseDate is var arg1 && result.ReleaseDate.HasValue ? result.ReleaseDate.Value > arg1 : (bool?)null).GetValueOrDefault())
                    {
                        continue;
                    }
                    _priorResultList.Add(result);
                }
            }
            catch (Exception ex)
            {
                Log.Error(ex.Message, ex);
                Trace.Write(ex.ToString());
                throw;
            }

        }

        /// <summary>
        /// Derived from m_orderAnayltePanels and m_orderAnalytes. Determine if the Report can be marked as released.
        /// </summary>
        public resultStatusType GetAnalyteStatus()
        {

            int i = (int)resultStatusType.Corrected;
            int x; // = 0

            foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
            {
                x = (int)p.GetStatus();
                if (x < i)
                    i = x;
            }
            foreach (ReportAnalyte a in _orderAnalytes.List)
            {
                x = (int)a.ResultStatus;
                if (x < i)
                    i = x;
            }

            return (resultStatusType)i;

        }


