        /// <summary>
        /// Used for outbound reporting.  Will return "Corrected" if any exist.
        /// </summary>
        /// <param name="orderableCode"></param>
        /// <returns></returns>
        /// <remarks></remarks>
        public resultStatusType GetGroupStatusForReporting(string orderableCode)
        {

            int i = (int)resultStatusType.Final;
            int x; // = 0

            foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
            {
                if (p.Panel.IsReportable && p.ContainsOrderCode(orderableCode))
                {
                    x = (int)p.GetStatus();
                    if (x == 3)
                        return resultStatusType.Corrected;
                    if (x < i)
                        i = x;
                }
            }
            foreach (ReportAnalyte a in _orderAnalytes.List)
            {
                if (a.Analyte.IsReportable && a.ContainsOrderCode(orderableCode))
                {
                    x = (int)a.ResultStatus;
                    if (x == 3)
                        return resultStatusType.Corrected;
                    if (x < i)
                        i = x;
                }
            }

            return (resultStatusType)i;

        }

