        public ReportAnalyte FindAnalyte(string analyteCode, bool searchPanels, int referenceLabId, transmitStatusType transmitStatus)
        {

            ReportAnalyte a;

            a = Analytes.FindFirst(analyteCode, referenceLabId, transmitStatus);
            if (!(a == null))
                return a;

            if (searchPanels)
            {
                foreach (ReportAnalytePanel p in AnalytePanels.List)
                {
                    a = p.Analytes.FindFirst(analyteCode, referenceLabId, transmitStatus);
                    if (!(a == null))
                        return a;
                }
            }

            return null;

        }

