        public ReportAnalyte FindAnalyteForRules(string analyteCode, bool searchPanels)
        {
            var listOfAnalytes = FindAll(analyteCode);
            var filteredListOfAnalytes = new List<ReportAnalyte>();
            if (listOfAnalytes.Count == 1)
            {
                return listOfAnalytes[0];
            }
            else
            {
                foreach (ReportAnalyte an in listOfAnalytes)
                {
                    if (!FilterResult(an, true, false))
                    {
                        filteredListOfAnalytes.Add(an);
                    }
                }
                if (filteredListOfAnalytes.Count == 1)
                {
                    return filteredListOfAnalytes[0];
                }
                else
                {
                    return null;
                }
            }
        }

        public List<ReportAnalyte> FindAll(string analyteCode, bool excludeNotPerformed = false, bool excludeEmptyResult = false)
        {
            var listOfAnalytes = new List<ReportAnalyte>();
            foreach (ReportAnalyte an in Analytes.List)
            {
                if ((an.Code ?? "") == (analyteCode ?? "") && !FilterResult(an, excludeNotPerformed, excludeEmptyResult))
                {
                    listOfAnalytes.Add(an);
                }
            }
            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {
                foreach (ReportAnalyte an in p.Analytes.List)
                {
                    if ((an.Code ?? "") == (analyteCode ?? "") && !FilterResult(an, excludeNotPerformed, excludeEmptyResult))
                    {
                        listOfAnalytes.Add(an);
                    }
                }
            }
            return listOfAnalytes;
        }

        private bool FilterResult(ReportAnalyte an, bool excludeNotPerformed, bool excludeEmptyResult)
        {
            if (excludeNotPerformed)
            {
                if (SharedFunctions.IsNotPerformedResult(an.ResultValue) || SharedFunctions.IsATP(an.ResultValue))
                {
                    return true;
                }
            }
            if (excludeEmptyResult)
            {
                if (string.IsNullOrEmpty(an.ResultValue))
                {
                    return true;
                }
            }
            return false;
        }

