        public ReportAnalyte FindAnalyteInPanel(string panelCode, string analyteCode)
        {

            ReportAnalyte a;
            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {
                if ((p.PanelCode ?? "") == (panelCode ?? ""))
                {
                    a = p.Analytes.FindFirst(analyteCode, 0, transmitStatusType.NotSet);
                    if (a is not null)
                        return a;
                }
            }
            return null;

        }

