        /// <summary>
        /// Returns an array of ReportComments that appear twice or more anywhere within the Report.
        /// </summary>
        /// <returns></returns>
        /// <remarks></remarks>
        public ReportComments GetDuplicateComments()
        {

            var ids = new Hashtable();
            var dupComments = new ReportComments(null);

            foreach (ReportAnalyte a in Analytes.List)
            {
                foreach (ReportComment c in a.Comments.List)
                {
                    if (!string.IsNullOrEmpty(c.ExternalId))
                    {
                        if (dupComments.Find(c.ExternalId) == null && ids.ContainsKey(c.ExternalId))
                        {
                            dupComments.List.Add(c);
                        }
                        else if (ids.ContainsKey(c.ExternalId) == false)
                        {
                            ids.Add(c.ExternalId, c.ExternalId);
                        }
                    }
                }
            }

            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {

                foreach (ReportAnalyte a in p.Analytes.List)
                {
                    foreach (ReportComment c in a.Comments.List)
                    {
                        if (!string.IsNullOrEmpty(c.ExternalId))
                        {
                            if (dupComments.Find(c.ExternalId) == null && ids.ContainsKey(c.ExternalId))
                            {
                                dupComments.List.Add(c);
                            }
                            else if (ids.ContainsKey(c.ExternalId) == false)
                            {
                                ids.Add(c.ExternalId, c.ExternalId);
                            }
                        }
                    }
                }

            }

            return dupComments;

        }

