        public ReportStatus GetReportStatus()
        {
            var maxReleaseDate = DateTime.Parse("1900-01-01");
            var rptStatusInfo = new ReportStatus();

            maxReleaseDate = ReportFinalDate();

            if (maxReleaseDate > DateTime.Parse("1900-01-01"))
            {
                rptStatusInfo.AccessionStatus = reportStatusType.Final;
                rptStatusInfo.DateReported = maxReleaseDate;
            }
            else if (IsPrelim())
            {
                rptStatusInfo.AccessionStatus = reportStatusType.Preliminary;
                rptStatusInfo.DateReported = maxReleaseDate;
            }
            else
            {
                // we dont care if anything is sent to reporting so don't bother with the date.
                rptStatusInfo.AccessionStatus = reportStatusType.Pending;
                rptStatusInfo.DateReported = maxReleaseDate;
            }

            return rptStatusInfo;

        }

        /// <summary>
        /// 
        /// if a check was made for IsFinal prior to calling this routine, no need to send True for checkIfFinal.
        /// This should only be sent as True if IsFinal has not been validated yet.
        /// </summary>
        /// <param name="checkIfFinal"></param>
        /// <returns></returns>
        /// <remarks></remarks>
        private bool IsPrelim(bool checkIfFinal = false)
        {
            // If isPrelim : some reportables have been released but report is not Final.
            // if not either, it will return "1/1/1900"
            bool bolIsPrelim = false;

            if (checkIfFinal)
            {
                // if this is Final, it can't be prelim
                if (IsFinal())
                    return false;
            }

            // not final.  Has anything been released?  if so, automatically return true.

            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.Analyte.IsReportable && a.HasBeenReleased())
                {
                    return true;
                }
            }

            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {
                if (p.Panel.IsReportable && p.HasBeenReleased())
                {
                    return true;
                }
            }

            return bolIsPrelim;

        }

        private DateTime ReportFinalDate()
        {
            // If isFinal and All reportables have been reported get the most recent Released date 
            // if not either, it will return "1/1/1900"
            var maxReleaseDate = DateTime.Parse("1900-01-01");

            if (IsFinal())
            {
                // We don't have to worry about this being COC or not at this point.  We already checked IsFinal which takes care of COC Final.
                foreach (ReportAnalyte a in Analytes.List)
                {
                    if (a.Analyte.IsReportable && (a.ResultStatus == resultStatusType.Final || a.ResultStatus == resultStatusType.Corrected))
                    {
                        maxReleaseDate = Conversions.ToDate(Interaction.IIf(a.ReleaseDate > maxReleaseDate, a.ReleaseDate, maxReleaseDate));
                    }

                }

                resultStatusType s;
                foreach (ReportAnalytePanel p in AnalytePanels.List)
                {

                    if (!p.Panel.IsReportable)
                        continue;
                    s = p.GetStatus();
                    if (s == resultStatusType.Final || s == resultStatusType.Corrected)
                    {
                        maxReleaseDate = Conversions.ToDate(Interaction.IIf(p.ReleaseDate > maxReleaseDate, p.ReleaseDate, maxReleaseDate));
                    }
                }
            }

            return maxReleaseDate;

        }

        public bool IsFinal()
        {

            // For COC.  need to check the isReviewed for each analyte.
            foreach (ReportAnalyte a in Analytes.List)
            {
                // For COC, all analytes must be Final or Corrected regardless if they are Reportable or not.

                // NA: 4/23/14
                if (IsCOC)
                {
                    if (!a.Analyte.IsReportable)
                        continue;
                    if (a.ResultStatus != resultStatusType.Final && a.ResultStatus != resultStatusType.Corrected)
                        return false;
                    if (a.IsCOCReviewed == false)
                        return false;
                }
                else
                {
                    if (!a.Analyte.IsReportable)
                        continue;
                    if (a.ResultStatus != resultStatusType.Final && a.ResultStatus != resultStatusType.Corrected)
                        return false;
                }

            }

            resultStatusType s;
            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {

                if (!p.Panel.IsReportable)
                    continue;
                s = p.GetStatus();
                // NA: 4/23/14
                if (IsCOC)
                {
                    if (s != resultStatusType.Final && s != resultStatusType.Corrected)
                    {
                        return false;
                    }
                    else
                    {
                        foreach (ReportAnalyte a in p.Analytes.List)
                        {
                            if (a.Analyte.IsReportable && a.IsCOCReviewed == false)
                            {
                                return false;
                            }
                        }
                    }
                }
                else if (s != resultStatusType.Final && s != resultStatusType.Corrected)
                    return false;

            }

            return true;

        }

