        /// No one should call this function except the rule engine
        public bool AddByTestCodeViaRule(string testCode)
        {
            bool ret = false;
            if (AddByTestCodeAndOrderedCode(testCode, "", SPMStatusValue.None))
            {
                // search report analyte
                foreach (ReportAnalyte ana in Analytes.List)
                {
                    if (ana.Code.Equals(testCode))
                    {
                        ana.ToFollowSent = true;
                        ret = true;
                        break;
                    }
                }
            }
            return ret;
        }

