        public bool AddByTestCodeAndOrderedCode(string testCode, string orderedTestCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {
            lock (_addTestLock)
            {
                CheckAndFlagIfResend();
            }
            Log.DebugFormat("AddByTestCodeAndOrderedCode testCode='{0}', orderedTestCode='{1}', accessionFacility='{2}', performFacility='{3}', spmOrderTestId='{4}' spmStatus='{5}", testCode, orderedTestCode, accessionFacility, performFacility, spmOrderTestId, spmStatus);
            if (Configuration.LISSettings.GetBool("AddTestFromTestMaster"))
            {
                return AddByTestCodeAndOrderedCodeTestMaster(testCode, orderedTestCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
            }
            else
            {
                return AddByTestCodeAndOrderedCodeLocal(testCode, orderedTestCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
