        private bool AddByTestCodeAndOrderedCodeLocal(string testCode, string orderedTestCode, string accessionFacility, string performFacility, long SPMOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {

            string orderCode = Conversions.ToString(Interaction.IIf(orderedTestCode.Equals(""), testCode, orderedTestCode.ToUpper()));
            // THIS CODE HERE DETERMINES WHERE THE TESTMASTER DATA IS PULLED FROM.

            var r = TestDetail.Fetch(testCode, 0);

            if (r.IsProfile)
            {

                foreach (TestAnalytePanel p in r.AnalytePanelList)
                    AddPanel(p, orderCode, accessionFacility, performFacility, spmStatus: spmStatus);
                foreach (TestAnalyte a in r.AnalyteList)
                    AddAnalyte(a, orderCode, accessionFacility, performFacility, spmStatus: spmStatus);
            }

            else if (r.IsPanel)
            {
                AddPanel(r.AnalytePanel, orderCode, accessionFacility, performFacility, SPMOrderTestId, spmStatus: spmStatus);
            }
            else
            {
                AddAnalyte(r.Analyte, orderCode, accessionFacility, performFacility, SPMOrderTestId, spmStatus: spmStatus);
            }

            return _testAdded;

        }

        private bool AddByTestCodeAndOrderedCodeTestMaster(string testCode, string orderedTestCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {

            string orderCode = Conversions.ToString(Interaction.IIf(orderedTestCode.Equals(""), testCode, orderedTestCode.ToUpper()));
            // THIS CODE HERE DETERMINES WHERE THE TESTMASTER DATA IS PULLED FROM.
            Log.DebugFormat("TestMasterWrapper.Fetch testCode='{0}', order='{1}'", testCode, ReferencedOrder.ID);
            var argorder = ReferencedOrder;
            var ti = TestMasterWrapper.Fetch(testCode, order: ref argorder);
            if (ti == null)
            {
                throw new Exception("Unable to add test.  Unable to retrieve test information from Test Master.  Test Code : " + testCode);
            }

            // 1/23/2012 - Even though profiles are handled here, currently SPM does not send them.
            if (ti.IsProfile)
            {
                foreach (TestInfo item in ti.Components)
                {
                    if (item.IsProfile)
                    {
                        AddByTestCodeAndOrderedCode(item.Code, orderCode, accessionFacility, performFacility, spmStatus: spmStatus);
                    }
                    else if (item.IsPanel)
                    {
                        AddPanel(item, orderCode, accessionFacility, performFacility, spmStatus: spmStatus);
                    }
                    else
                    {
                        AddAnalyte(item, orderCode, accessionFacility, performFacility, spmStatus: spmStatus);
                    }
                }
            }
            else if (ti.IsPanel)
            {
                Log.Debug($"AddPanel code={ti.Code} spmStatus={spmStatus}");
                AddPanel(ti, orderCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
            }
            else
            {
                Log.Debug($"AddAnalyte code={ti.Code} spmStatus={spmStatus}");
                AddAnalyte(ti, orderCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
            }

            return _testAdded;

        }

        private void AddPanel(TestInfo ti, string orderCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {
            lock (_addTestLock)
            {
                ReportAnalytePanel p;
                ReportAnalyte x;
                p = AnalytePanels.Find(ti.Code);
                if (p == null)
                {
                    p = AnalytePanels.List.FindDeleted(ti.Code);
                    // If Not IsNothing(p) AndAlso p.GetStatus <> resultStatusType.Pending AndAlso p.ContainsOrderCode(orderCode) Then
                    if (!(p == null) && p.GetStatus() != resultStatusType.Pending)
                    {
                        AnalytePanels.List.UnDeletePanel(p);
                        p.RemoveOrderingCodes();
                        p.AddOrderingCode(orderCode);
                        p.SPMStatus = spmStatus;
                        _testAdded = true;
                    }
                    else
                    {
                        p = AnalytePanels.Add(ti, orderCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
                        _testAdded = true;
                    }
                    if (p is not null)
                    {
                        foreach (ReportAnalyte a in p.Analytes.List)
                        {
                            x = FindAnalyte(a.Code, false);
                            a.SPMStatus = spmStatus;
                            CopyAnalyteValues(a, x);
                        }
                    }
                }
                else
                {
                    p.AddOrderingCode(orderCode);
                }
            }

        }

        private void AddAnalyte(TestInfo item, string orderCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {
            lock (_addTestLock)
            {
                ReportAnalyte a;
                ReportAnalyte x;
                a = Analytes.FindFirst(item.Code);
                if (a == null)
                {
                    a = Analytes.List.FindFirstDeleted(item.Code);
                    if (!(a == null) && a.ResultStatus != resultStatusType.Pending)
                    {
                        Analytes.List.UnDeleteAnalyte(a);
                        a.RemoveOrderingCodes();
                        a.AddOrderingCode(orderCode);
                        a.SPMStatus = spmStatus;
                        Log.Debug($"AddAnalyte A code={item.Code} spmStatus={spmStatus} a.spmStatus={a.SPMStatus}");
                        _testAdded = true;
                    }
                    else
                    {
                        x = FindAnalyte(item.Code, true); // look for an existing analyte in case one exists with a value
                        a = Analytes.Add(item, orderCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
                        CopyAnalyteValues(a, x);
                        _testAdded = true;
                        a.CodeTypeId = item.CodeTypeId;
                        Log.Debug($"AddAnalyte B code={item.Code} spmStatus={spmStatus} a.spmStatus={a.SPMStatus}");
                    }
                }
                else
                {
                    a.AddOrderingCode(orderCode);
                    Log.Debug($"AddAnalyte C a.spmStatus={a.SPMStatus}");
                }
            }
        }

        public void AddPanel(TestAnalytePanel ti, string orderCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {
            lock (_addTestLock)
            {
                ReportAnalytePanel p;
                ReportAnalyte x;
                p = AnalytePanels.Find(ti.PanelCode);
                if (p == null)
                {
                    p = AnalytePanels.List.FindDeleted(ti.PanelCode);
                    if (!(p == null) && p.GetStatus() != resultStatusType.Pending)
                    {
                        AnalytePanels.List.UnDeletePanel(p);
                        _testAdded = true;
                    }
                    else
                    {
                        p = AnalytePanels.Add(ti, orderCode, accessionFacility, performFacility, spmOrderTestId, spmStatus);
                        _testAdded = true;
                    }
                    if (p is not null)
                    {
                        foreach (ReportAnalyte a in p.Analytes.List)
                        {
                            x = FindAnalyte(a.Code, false);
                            CopyAnalyteValues(a, x);
                        }
                    }
                }
                else
                {
                    p.AddOrderingCode(orderCode);
                }
            }

        }

        public void AddAnalyte(TestAnalyte item, string orderCode, string accessionFacility, string performFacility, long spmOrderTestId = 0, SPMStatusValue spmStatus = SPMStatusValue.None)
        {
            lock (_addTestLock)
            {
                ReportAnalyte a;
                ReportAnalyte x;
                a = Analytes.FindFirst(item.Code);
                if (a == null)
                {
                    a = Analytes.List.FindFirstDeleted(item.Code);
                    if (!(a == null) && a.ResultStatus != resultStatusType.Pending)
                    {
                        Analytes.List.UnDeleteAnalyte(a);
                        _testAdded = true;
                    }
                    else
                    {
                        x = FindAnalyte(item.Code, true); // look for an existing analyte in case one exists with a value
                        a = Analytes.Add(item, orderCode, accessionFacility, performFacility, spmOrderTestId, spmStatus: spmStatus);
                        CopyAnalyteValues(a, x);
                        _testAdded = true;
                    }
                }
                else
                {
                    a.AddOrderingCode(orderCode);
                }
            }

        }

        private void CopyAnalyteValues(ReportAnalyte target, ReportAnalyte source)
        {

            if (target is not null && source is not null && source.ResultStatus != resultStatusType.Pending && !string.IsNullOrEmpty(source.ResultValue))
            {
                UpdateResultAnalyte(target, source.ResultValue, source.PerformingFacility, source.AccessioningFacility, source.ResultStatus == resultStatusType.OnHold, "");
                target.ResultStatus = source.ResultStatus;
                target.IsCopiedAnalyte = true;
                target.ToFollowSent = true;
                if (source.Comments is not null & source.Comments.List.Count > 0)
                {
                    foreach (ReportComment c in source.Comments.List)
                        target.Comments.AddComment(c, c.IsAutoAdded);
                }
            }

        }

        public void RemoveTest(string testCode)
        {

            for (int i = 0, loopTo = _orderAnalytes.List.Count - 1; i <= loopTo; i++)
            {
                if ((_orderAnalytes.List[i].Code ?? "") == (testCode ?? ""))
                {
                    _orderAnalytes.Remove(_orderAnalytes.List[i]);
                    break;
                }
            }

            for (int i = 0, loopTo1 = _orderAnalytePanels.List.Count - 1; i <= loopTo1; i++)
            {
                if ((_orderAnalytePanels.List[i].PanelCode ?? "") == (testCode ?? ""))
                {
                    _orderAnalytePanels.Remove(_orderAnalytePanels.List[i]);
                    break;
                }
            }

        }

        public void RemoveComments(string testCode)
        {

            foreach (ReportAnalyte a in _orderAnalytes.List)
            {
                if ((a.Code ?? "") == (testCode ?? ""))
                {
                    a.RemoveAllComments();
                }
            }

            foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
            {
                if ((p.PanelCode ?? "") == (testCode ?? ""))
                {
                    p.Comments.DeleteAll();
                }

                foreach (ReportAnalyte a in p.Analytes.List)
                {
                    if ((a.Code ?? "") == (testCode ?? ""))
                    {
                        a.RemoveAllComments();
                    }
                }
            }

        }

        public bool HasReleased()
        {

            // we need to handle COC slightly different.
            if (IsCOC)
            {
                foreach (ReportAnalytePanel p in AnalytePanels.List)
                {
                    if (p.Panel.IsReportable && p.TransmitStatus == transmitStatusType.Released)
                    {
                        // if any of the analytes in this panel have been approved, then YES.  Otherwise, no
                        foreach (ReportAnalyte a in p.Analytes.List)
                        {
                            if (a.Analyte.IsReportable && a.TransmitStatus == transmitStatusType.Released && a.IsCOCReviewed)
                            {
                                return true;
                            }
                        }
                    }
                }

                foreach (ReportAnalyte a in Analytes.List)
                {
                    if (a.Analyte.IsReportable && a.TransmitStatus == transmitStatusType.Released && a.IsCOCReviewed)
                        return true;
                }
            }
            else
            {
                foreach (ReportAnalytePanel p in AnalytePanels.List)
                {
                    if (p.Panel.IsReportable && p.TransmitStatus == transmitStatusType.Released)
                        return true;
                }

                foreach (ReportAnalyte a in Analytes.List)
                {
                    if (a.Analyte.IsReportable && a.TransmitStatus == transmitStatusType.Released)
                        return true;
                }
            }

            return false;

        }

        public bool HasReleased(string category)
        {

            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {
                if ((p.Panel.Category ?? "") == (category ?? "") && p.Panel.IsReportable && p.TransmitStatus == transmitStatusType.Released)
                    return true;
            }

            foreach (ReportAnalyte a in Analytes.List)
            {
                if ((a.Analyte.Category ?? "") == (category ?? "") && a.Analyte.IsReportable && a.TransmitStatus == transmitStatusType.Released)
                    return true;
            }

            return false;

        }

        public bool HasPending()
        {

            foreach (ReportAnalytePanel p in AnalytePanels.List)
            {
                // 2/21/2014 NA. Held for Rerun is part of HasPending
                // If p.Panel.IsReportable AndAlso (p.TransmitStatus = transmitStatusType.PendingRelease OrElse p.TransmitStatus = transmitStatusType.HeldForRerun) Then Return True

                // 5/22/14 : Panels may be prelim released but have pending components.
                if (p.Panel.IsReportable)
                {
                    if (p.TransmitStatus == transmitStatusType.PendingRelease || p.TransmitStatus == transmitStatusType.HeldForRerun)
                    {
                        return true;
                    }
                    else
                    {
                        foreach (ReportAnalyte a in p.Analytes.List)
                        {
                            if (a.Analyte.IsReportable && a.Analyte.IsRequired && (a.TransmitStatus == transmitStatusType.PendingRelease || a.TransmitStatus == transmitStatusType.HeldForRerun || a.HasSampleRequest()))
                            {
                                return true;
                            }
                        }
                    }
                }
            }

            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.Analyte.IsReportable && (a.TransmitStatus == transmitStatusType.PendingRelease || a.TransmitStatus == transmitStatusType.HeldForRerun || a.HasSampleRequest()))
                    return true;
            }

            return false;

        }



