        #region Friend Methods

        internal object CheckOrderableStatusReleased(string orderableCode, string excludeCode)
        {

            foreach (ReportAnalyte a in _orderAnalytes.List)
            {
                if ((a.Code ?? "") != (excludeCode ?? "") && a.ContainsOrderCode(orderableCode))
                {
                    if (!a.HasBeenReleased())
                        return false;
                }
            }
            foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
            {
                if ((p.PanelCode ?? "") != (excludeCode ?? "") && p.ContainsOrderCode(orderableCode))
                {
                    if (!p.HasBeenReleased())
                        return false;
                }
            }

            return true;

        }

        internal object SetOrderableStatusFinal(string orderableCode)
        {

            foreach (ReportAnalyte a in _orderAnalytes.List)
            {
                if (a.ContainsOrderCode(orderableCode))
                {
                    if (a.HasBeenReleased())
                        a.ResultStatus = resultStatusType.Final;
                }
            }
            foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
            {
                if (p.ContainsOrderCode(orderableCode))
                {
                    if (p.HasBeenReleased())
                        p.SetFinal();
                }
            }

            return true;

        }

        /// <summary>
        /// This will automatically add/re-add Tests that have been deleted off the report
        /// </summary>
        /// <param name="order"></param>
        /// <param name="tests"></param>
        /// <returns></returns>
        /// <remarks></remarks>
        internal static Report CreateResults(Order order, OrderReport.TestCodeStruct[] tests)
        {

            try
            {

                var timertotal = new Stopwatch();
                long totalelapsedTime = timertotal.ElapsedMilliseconds;


                timertotal.Start();

                var timer = new Stopwatch();
                long elapsedTime = timer.ElapsedMilliseconds;

                timer.Start();
                var r = CreateReport(order);
                timer.Stop();
                elapsedTime = timer.ElapsedMilliseconds;
                timer.Reset();
                Log.DebugFormat("CreateReport took {0} milliseconds", elapsedTime);


                // Loop through all the tests in the order, look them up in the lab namespace, and add
                // to the OrderResult
                foreach (OrderReport.TestCodeStruct t in tests)
                {
                    timer.Start();
                    if (!r.AddByTestCodeAndOrderedCode(t.TestCode, t.OrderedTestCode, t.AccessioningFacility, t.PerformingFacility, t.SPMOrderTestId, spmStatus: t.SPMStatus))
                    {

                    }
                    timer.Stop();
                    elapsedTime = timer.ElapsedMilliseconds;
                    timer.Reset();
                    Log.DebugFormat("Add testcode {0} took {1} milliseconds", t.TestCode, elapsedTime);
                }

                r.FlagDirty();

                timertotal.Stop();
                totalelapsedTime = timertotal.ElapsedMilliseconds;
                timertotal.Reset();
                Log.InfoFormat(
                 "Entity: {Entity}; Event: {Event}; Message: {Message}; ElapsedTime: {ElapsedMs} ms",
                 "Tests",
                 "Add",
                 "Total time taken to add tests.",
                 totalelapsedTime);

                return r;
            }

            catch (Exception ex)
            {
                Log.Error(ex.Message, ex);
                throw;
            }


        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="order">The Order to create the report from.</param>
        /// <param name="onlyNewCodes">Create tests that were added to the Order after the Order was created or fetched.</param>
        /// <returns></returns>
        /// <remarks></remarks>
        internal static Report CreateResults(Order order, bool onlyNewCodes)
        {

            try
            {

                var r = CreateReport(order);

                // Loop through all the tests in the order, look them up in the lab namespace, and add
                // to the OrderResult
                foreach (OrderTest t in order.Tests.List)
                {
                    if (onlyNewCodes && t.m_loadedFromDatabase == false || onlyNewCodes == false)
                    {
                        string defaultDivisionCode = Configuration.AppSettings.GetList("Bioreference.LIS:DefaultDivisionCode").ToArray()[0];
                        if (!r.AddByTestCodeAndOrderedCode(t.TestCode, t.OrderedTestCode, defaultDivisionCode, defaultDivisionCode, spmStatus: t.SPMStatus))
                        {

                        }
                    }
                }

                CheckCalcPerfomingLocation(r);

                r.FlagDirty();
                return r;
            }

            catch (Exception ex)
            {
                Log.Error(ex.Message, ex);
                throw;
            }

        }

        public static void CheckCalcPerfomingLocation(Report r)
        {
            if (r.HasCalcAnalytes)
            {
                ReportAnalytePanel panel = null;
                ReportAnalyte analyte = null;
                var analyteList = new List<string>();
                var panelList = new List<string>();

                // Changed this function to first load the Analytes and Panels in lists, then loop over them.
                // This was done because calculations could cause rules to fire, which would remove Analytes/Panels and cause an enumeration exception

                // '**********************************************************************
                foreach (ReportAnalyte an in r.Analytes.List)
                    analyteList.Add(an.Code);

                string strCalcPerfLoc = "";
                bool bolReplaceFacility = false;

                // First we check for Analytes that exist directly on the report.
                foreach (string s in analyteList)
                {
                    analyte = r.FindAnalyte(s, false);
                    if (!(analyte == null))
                    {
                        if (analyte.Analyte.IsCalculation)
                        {
                            strCalcPerfLoc = "";
                            bolReplaceFacility = false;
                            ReportAnalyte ra = null;
                            foreach (string testCode in analyte.Analyte.Calculation.TestCodeList)
                            {
                                ra = r.FindAnalyte(testCode, true);
                                if (!(ra == null))
                                {
                                    if (ra.PerformingFacility.Trim().Equals(""))
                                    {
                                        bolReplaceFacility = false;
                                        break;
                                    }
                                    if (string.IsNullOrEmpty(strCalcPerfLoc))
                                    {
                                        strCalcPerfLoc = ra.PerformingFacility;
                                        bolReplaceFacility = true;
                                    }
                                    else if (!strCalcPerfLoc.ToLower().Equals(ra.PerformingFacility.ToLower()))
                                    {
                                        bolReplaceFacility = false;
                                        break;
                                    }
                                }
                            }
                            if (bolReplaceFacility)
                            {
                                analyte.SetPerformingFacility(strCalcPerfLoc);
                            }
                        }
                    }
                }
                // '**********************************************************************

                // '**********************************************************************
                foreach (ReportAnalytePanel p in r.AnalytePanels.List)
                    panelList.Add(p.PanelCode);

                // We need to check ALL the panels.
                foreach (string s in panelList)
                {
                    panel = r.FindAnalytePanel(s);
                    if (!(panel == null))
                    {
                        foreach (ReportAnalyte an in panel.Analytes.List)
                        {
                            if (an.Analyte.IsCalculation)
                            {
                                strCalcPerfLoc = "";
                                bolReplaceFacility = false;
                                ReportAnalyte ra = null;
                                foreach (string testCode in an.Analyte.Calculation.TestCodeList)
                                {
                                    ra = r.FindAnalyte(testCode, true);
                                    if (!(ra == null))
                                    {
                                        if (string.IsNullOrEmpty(strCalcPerfLoc))
                                        {
                                            strCalcPerfLoc = ra.PerformingFacility;
                                            bolReplaceFacility = true;
                                        }
                                        else if (!strCalcPerfLoc.ToLower().Equals(ra.PerformingFacility.ToLower()))
                                        {
                                            bolReplaceFacility = false;
                                            break;
                                        }
                                    }
                                }
                                if (bolReplaceFacility)
                                {
                                    an.SetPerformingFacility(strCalcPerfLoc);
                                }
                            }
                        }
                    }
                }
                // '**********************************************************************
            }
        }

