        {

            var da = new DataWrapper(Configuration.ConnectionString);
            DataTable[] dt;
            bool isTNP = false;
            var @params = new List<DbParameter>() { (DbParameter)da.CreateParameter("@AccessionNbr", DbType.String, AccessionNbr), (DbParameter)da.CreateParameter("@AnalyteCode", DbType.String, AnalyteCode) };
            dt = da.ExecuteProcedure("lis_IsAnalyteTNP", @params.ToArray());
            if (dt is not null && dt.Count() > 0 && dt[0].Rows.Count > 0)
