        private static Report CreateReport(Order order)
        {

            var r = new Report();
            r._referencedOrder = order;

            r._orderId = order.ID;
            r._accessionNbr = order.AccessionNbr;

            r._dob = order.Patient.DateOfBirth;
            r._gender = order.Patient.Gender;
            r._accountNbr = order.AccountNumber;
            r._ageNbr = order.Patient.AgeNumber;
            r._ageType = order.Patient.AgeType;

            // NA: 3/24/2014 COC initialization.
            r._isCOC = r.DoesNineDigitAccessionStartsWith("19");

            return r;

        }


