        public override List<CompareResult> CompareObject(object obj)
        {

            Report report = (Report)obj;

            var list = new List<CompareResult>();

            // 'Get base compare values
            list.AddRange(base.CompareObject(obj));

            list.AddRange(CompareResult.CompareObjects(Analytes.List, report.Analytes.List));
            list.AddRange(CompareResult.CompareObjects(AnalytePanels.List, report.AnalytePanels.List));
            list.AddRange(CompareResult.CompareObjects(Comments.List, report.Comments.List));

            return list;

        }

