        protected override void DataFactory_Delete(object criteria)
        {

            Criteria c = (Criteria)criteria;
            var da = new DataWrapper(Configuration.ConnectionString);
            var @param = new DbParameter[1];

            try
            {

                @param[0] = (DbParameter)da.CreateParameter("@ReportId", DbType.Int64, c.ReportId);
                da.ExecuteNonQuery("lis_Report_Delete", @param);

                FlagDeleted();
                FlagClean();
            }

            catch (Exception ex)
            {
                Log.Error(ex.Message, ex);
                Trace.Write(ex.ToString());
                throw;
            }


        }

        protected override void DataFactory_Fetch(object criteria)
        {

            Criteria c = (Criteria)criteria;
            var da = new DataWrapper(Configuration.ConnectionString);
            DataTable[] dt = null;
            this._usecache = c.UseCache;
            this._cacheKey = c.CacheKey;

            try
            {
                //if (this._usecache)
                //{
                //    dt = LoadDataTablesAsJSON(this._cacheKey);
                //}
                if (dt == null)
                {
                    if (c.EUID > 0L)
                    {
                        LoadPrevEUIDReportHavingCode(c.EUID, c.Code);
                        return;
                    }
                    if (c.FetchNext)
                    {
                        DbParameter @param;
                        @param = (DbParameter)da.CreateParameter("@OutboundChannelId", DbType.Int32, c.OutboundChannelId);
                        dt = da.ExecuteProcedure("lis_ReportNextOutbound_Fetch", @param);
                    }
                    else
                    {
                        var @param = new List<DbParameter>();
                        @param.Add((DbParameter)da.CreateParameter("@ReportId", DbType.Int64, c.ReportId));
                        @param.Add((DbParameter)da.CreateParameter("@AccessionNbr", DbType.String, c.AccessionNbr));
                        @param.Add((DbParameter)da.CreateParameter("@LoadAudit", DbType.Boolean, c.LoadAudit));
                        if (c.DateServiced > DateTime.Parse("1900-01-01"))
                        {
                            @param.Add((DbParameter)da.CreateParameter("@DateServiced", DbType.DateTime, c.DateServiced));
                        }
                        dt = da.ExecuteProcedure("lis_Report_Fetch", @param.ToArray());
                        //if (this._usecache)
                        //{
                        //    SaveDataTablesAsJSON(dt, this._cacheKey);
                        //}

                        if (dt[0].Rows.Count > 0)
                        {
                            Load(dt, c.LoadAudit, c.ReferenceOrder);
                        }
                    }
                }
                else
                {
                    if (dt[0].Rows.Count > 0)
                    {
                        Load(dt, c.LoadAudit, c.ReferenceOrder);
                    }

                }
            }
            catch (Exception ex)
            {
                Log.Error(ex.Message, ex);
                Trace.Write(ex.ToString());
                throw;

            }

        }

