        public void LoadPrevEUIDReportHavingCode(long euid, string code)
        {
            var da = new DataWrapper(Configuration.ConnectionString);
            DataTable[] dt;

            try
            {

                var @param = new List<DbParameter>();
                @param.Add((DbParameter)da.CreateParameter("@EUID", DbType.Int64, euid));
                @param.Add((DbParameter)da.CreateParameter("@Code", DbType.String, code));
                dt = da.ExecuteProcedure("lis_fetch_previousEUIDAccession", @param.ToArray());
                if (dt[0].Rows.Count > 0)
                {
                    Load(dt, false, _referencedOrder);
                }
            }
            catch (Exception ex)
            {
                Log.Error(ex.Message, ex);
                Trace.Write(ex.ToString());
                throw;
            }

        }

