        public bool IsSentToFollow
        {
            get
            {
                bool followSent = false;                                                                           // 
                foreach (ReportAnalyte a in _orderAnalytes.List)                                                         // 
                {
                    if (a.ToFollowSent == false)                                                                          // 
                    {
                        followSent = true;                                                                                   // 
                        break;                                                                                            // 
                    }                                                                                                  // 
                }                                                                                                        // 
                if (!followSent)                                                                                      // 
                {
                    foreach (ReportAnalytePanel p in _orderAnalytePanels.List)                                           // 
                    {
                        if (p.ToFollowSent == false)                                                                      // 
                        {
                            followSent = true;                                                                               // 
                            break;                                                                                        // 
                        }                                                                                              // 
                    }                                                                                                    // 
                }
                return followSent;
            }
        }

        protected override void DataFactory_Save()
        {

            var da = new DataWrapper(Configuration.ConnectionString);
            var paramList = new List<DbParameter>();

            paramList.Add((DbParameter)da.CreateParameter("@ReportId", DbType.Int64, _id, ParameterDirection.InputOutput));
            paramList.Add((DbParameter)da.CreateParameter("@OrderId", DbType.Int64, _orderId));
            paramList.Add((DbParameter)da.CreateParameter("@DateCreated", DbType.DateTime, _dateCreated, ParameterDirection.InputOutput));
            paramList.Add((DbParameter)da.CreateParameter("@DateUpdated", DbType.DateTime, _dateUpdated, ParameterDirection.InputOutput));
            paramList.Add((DbParameter)da.CreateParameter("@SpecimenComment", DbType.String, _specimenComment));
            if (_resultDate > DateTime.Parse("1900-01-01"))
                paramList.Add((DbParameter)da.CreateParameter("@ResultDate", DbType.DateTime, _resultDate));
            paramList.Add((DbParameter)da.CreateParameter("@HasPending", DbType.Boolean, HasPending()));
            paramList.Add((DbParameter)da.CreateParameter("@HasReleased", DbType.Boolean, _needToResendResults || HasReleased()));

            // NART HERE comment out these lines to publish to CURRENT LIVE prior to upgrade.
            paramList.Add((DbParameter)da.CreateParameter("@IsCOC", DbType.Boolean, _isCOC));

            paramList.Add((DbParameter)da.CreateParameter("@ParentReportId", DbType.Int64, _parentReportId));
            paramList.Add((DbParameter)da.CreateParameter("@ChildReportId", DbType.Int64, _childReportId));
            paramList.Add((DbParameter)da.CreateParameter("@SpecimenSummary", DbType.String, _specimenSummary));
            // .Add(da.CreateParameter("@ProfileTNP", DbType.String, String.Join(",", _profileTNP)))

            // ''''' Send SendToFollow value depending on whether ToFollowSent is False for any analyte or panel ''''''''''
            bool sendToFollow = false;                                                                           // 
            foreach (ReportAnalyte a in _orderAnalytes.List)                                                         // 
            {
                if (!a.ToFollowSent && !a.IsPresumptiveHold)                                                                          // 
                {
                    sendToFollow = true;                                                                                   // 
                    break;                                                                                            // 
                }                                                                                                  // 
            }                                                                                                        // 
            if (!sendToFollow)                                                                                      // 
            {
                foreach (ReportAnalytePanel p in _orderAnalytePanels.List)                                           // 
                {
                    if (!p.ToFollowSent && !p.IsPresumptiveHold)                                                                      // 
                    {
                        sendToFollow = true;                                                                               // 
                        break;                                                                                        // 
                    }                                                                                              // 
                }                                                                                                    // 
            }                                                                                                      // 
                                                                                                                   // ''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''
            paramList.Add((DbParameter)da.CreateParameter("@SendToFollow", DbType.Boolean, sendToFollow));                                       // 

            DbParameter[] @params = paramList.ToArray();

            // 'We use the transaction scope when saving the Report. If any sql failures, all transaction should roll back.
            var options = new TransactionOptions();
            options.IsolationLevel = System.Transactions.IsolationLevel.ReadCommitted;
            options.Timeout = new TimeSpan(0, 2, 0);

            using (var scope = new TransactionScope(TransactionScopeOption.Required, options))
            {
                var returnParams = da.ExecuteNonQuery("lis_Report_Save", @params);

                _id = Conversions.ToLong(returnParams["@ReportId"].Value);
                _dateCreated = Conversions.ToDate(returnParams["@DateCreated"].Value);
                _dateUpdated = Conversions.ToDate(returnParams["@DateUpdated"].Value);

                _comments.Update();
                // NA: Get the list of AuditItem in this object after issuing the Clean so all properties are correctly populated.
                _auditItemList.AddRange(_comments.GetAuditItems());

                _orderAnalytes.Update();
                // NA: Get the list of AuditItem in this object after issuing the Clean so all properties are correctly populated.
                _auditItemList.AddRange(_orderAnalytes.GetAuditItems());


                _orderAnalytePanels.Update();
                // NA: Get the list of AuditItem in this object after issuing the Clean so all properties are correctly populated.
                _auditItemList.AddRange(_orderAnalytePanels.GetAuditItems());

                foreach (ReportCommentGroup cg in m_reportCommentGroups)
                {
                    if (cg.IsNew)
                        cg.Update();
                }

                foreach (OutboundMessage o in _outboundMessages)
                {
                    // future state
                    //try
                    //{
                    //    ReflexEvent?.Invoke(this, new ReflexEventData()
                    //    {
                    //        AccessionNumber = o.AccessionNumber,
                    //        OrderedCode = o.OrderedCode,
                    //        ReflexCode = o.ReflexCode,
                    //        DateOrdered = o.DateOrdered,
                    //        ActionType = o.ActionType
                    //    });
                    //    o.MarkAsProcessed();    // save to table as processed
                    //}
                    //catch (Exception)
                    //{
                    //    Log.Warn($"Unable to generate reflex message for {o.AccessionNumber}");
                    //}
                    o.Update();
                }

                if (!(_referencedOrder == null)) // 'this could of been loaded by adding comments, need to persist            
                {
                    _referencedOrder.Save();
                    _auditItemList.AddRange(_referencedOrder.GetFormattedAuditItems);
                }

                if (!(_outboundAllergenQueueItem == null))
                {
                    _outboundAllergenQueueItem.Update();
                }

                // check if the Objects for ExternalCalcLabQueue are not null.  If not null, then save them as well.

                if (!(_externalCalcLabQueue == null))
                {
                    _externalCalcLabQueue.Save();
                }

                if (fail4K)
                {
                    string subject = $"4K Calculation Skipped ({Configuration.LISSettings.GetString("EnvironmentName")})";
                    string body = $"Accession#: {AccessionNbr} Acct#: {AccountNumber} DOS: {DateServiced}{Constants.vbCrLf}{fail4KMessage}{Constants.vbCrLf}Please review.";
                    SharedFunctions.SendMail("noreply@bioreference.com", (List<string>)Configuration.LISSettings.GetList("FourK_AOE_Notify"), subject, body);
                }

                scope.Complete();

            }

            // NA: Get the list of AuditItem in this object after issuing the Clean so all properties are correctly populated.
            _auditItemList.AddRange(GetAuditItemsAndClean(true));
            // Reset the Audit items for report and all its agregated objects
            ResetAudit();
            _orderAnalytes.ResetAudit();
            _comments.ResetAudit();
            _orderAnalytePanels.ResetAudit();

        }

        private void Load(DataTable[] datatables, bool loadAudit, Order referenceOrder)
        {
            LoadAudit = loadAudit;

            // Load up the main Report.
            {
                var withBlock = datatables[0].Rows[0];
                _id = Conversions.ToLong(withBlock["ReportId"]);
                _dateCreated = Conversions.ToDate(withBlock["DateCreated"]);
                _dateUpdated = Conversions.ToDate(withBlock["DateUpdated"]);
                _orderId = Conversions.ToLong(withBlock["OrderID"]);
                _accessionNbr = Conversions.ToString(withBlock["AccessionNbr"]);
                _dob = Conversions.ToString(withBlock["DOB"]);
                _gender = (Common.Gender)Conversions.ToInteger(withBlock["GenderType"]);
                _ageType = Conversions.ToString(withBlock["AgeType"]);
                _ageNbr = Conversions.ToInteger(withBlock["AgeNbr"]);
                _dateServiced = Conversions.ToDate(withBlock["DateServiced"]);
                _dateCollected = Conversions.ToDate(withBlock["DateCollected"]);
                _accountNbr = Conversions.ToString(withBlock["AccountNumber"]);
                _specimenComment = Conversions.ToString(withBlock["SpecimenComment"]).NormalizeToWindows();
                _parentReportId = Conversions.ToInteger(withBlock["ParentReportId"]);
                _childReportId = Conversions.ToInteger(withBlock["ChildReportId"]);
                _specimenSummary = Conversions.ToString(withBlock["SpecimenSummary"]).NormalizeToWindows();

                // NA: 3/24/2014 - COC information retrieved
                // NART HERE comment out these lines to publish to CURRENT LIVE prior to upgrade.
                _isCOC = Conversions.ToBoolean(withBlock["IsCOC"]);
                
                _has4ktest = Conversions.ToBoolean(withBlock["Has4kTest"]);

                // _profileTNP = New List(Of String)
                // _profileTNP.AddRange(.Item("ProfileTNP").ToString().Split(New Char() {","}, StringSplitOptions.RemoveEmptyEntries))

            }

            if (referenceOrder is not null)
            {
                _referencedOrder = referenceOrder;
                _orderId = referenceOrder.ID;
                _accessionNbr = referenceOrder.AccessionNbr;
                _dob = referenceOrder.Patient.DateOfBirth;
                _gender = referenceOrder.Patient.Gender;
                _ageType = referenceOrder.Patient.AgeType;
                _ageNbr = referenceOrder.Patient.AgeNumber;
                _dateServiced = referenceOrder.DateOfService;
                _dateCollected = referenceOrder.DateOfCollection;
                _accountNbr = referenceOrder.AccountNumber;
            }

            FlagClean();  // Execute asap to load concurrency object

            // Load up all the ReportAnalytePanels and ReportAnalytes
            int apID = 0; // AnalytePanelID
            ReportAnalytePanel oap = null;
            ReportAnalyte oa = null;
            {
                ref var withBlock1 = ref datatables[1];
                foreach (DataRow r in withBlock1.Rows)
                {
                    if (Conversions.ToBoolean(Operators.ConditionalCompareObjectNotEqual(r["ReportAnalytePanelID"], 0, false)))
                    {
                        if (Conversions.ToBoolean(Operators.ConditionalCompareObjectNotEqual(r["ReportAnalytePanelID"], apID, false)))
                        {
                            oap = new ReportAnalytePanel(this, loadAudit);
                            oap.Load(r);
                            if (Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(r["IsPanelDeleted"], false, false)))
                            {
                                _orderAnalytePanels.List.Add(oap);
                                // 'Add to hash for rules evaluation
                                AddToTestCodeHash(Conversions.ToString(r["PanelCode"]));
                            }
                            else
                            {
                                _orderAnalytePanels.List.AddToArchiveDeletedList(oap);
                            }
                            apID = Conversions.ToInteger(r["ReportAnalytePanelID"]);
                        }

                        if (Conversions.ToBoolean(Operators.ConditionalCompareObjectNotEqual(r["ReportAnalyteId"], 0, false)))
                        {
                            oa = new ReportAnalyte(oap, loadAudit);
                            oa.Load(r);
                            if (oa.Analyte.IsCalculation)
                                m_hasCalcAnalytes = true;

                            if (Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(r["IsAnalyteDeleted"], false, false)))
                            {
                                oap.Analytes.Add(oa);
                            }
                            else
                            {
                                oap.Analytes.List.AddToArchiveDeletedList(oa);
                            }
                        }
                    }

                    else
                    {

                        oa = new ReportAnalyte(this, loadAudit);
                        oa.Load(r);
                        if (oa.Analyte.IsCalculation)
                            m_hasCalcAnalytes = true;

                        if (Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(r["IsAnalyteDeleted"], false, false)))
                        {
                            Analytes.Add(oa);
                            // 'Add to hash for rules evaluation
                            AddToTestCodeHash(Conversions.ToString(r["RefAnalyteCode"]));
                        }
                        else
                        {
                            Analytes.List.AddToArchiveDeletedList(oa);
                        }

                    }

                }
            }
            // Load up the Order Comments
            var ptype = orderParentType.Unknown;
            ReportComment oc = null;
            bool isItemDeleted = false;
            {
                ref var withBlock2 = ref datatables[2];
                foreach (DataRow r in withBlock2.Rows)
                {
                    isItemDeleted = Conversions.ToBoolean(r["IsDeleted"]);
                    ptype = (orderParentType)Conversions.ToInteger(r["ParentType"]);
                    switch (ptype)
                    {
                        case orderParentType.Report:
                            {
                                oc = new ReportComment(this, loadAudit);
                                oc.Load(r);
                                if (!isItemDeleted)
                                {
                                    _comments.List.Add(oc);
                                }
                                else
                                {
                                    _comments.List.AddToArchiveDeleteList(oc);
                                }

                                break;
                            }
                        case orderParentType.ReportAnalytePanel:
                            {
                                var p = AnalytePanels.Find(Conversions.ToInteger(r["ReportAnalytePanelId"]), true);
                                oc = new ReportComment(p, loadAudit);
                                oc.Load(r);
                                if (!isItemDeleted)
                                {
                                    p.Comments.List.Add(oc);
                                }
                                else
                                {
                                    p.Comments.List.AddToArchiveDeleteList(oc);
                                }

                                break;
                            }
                        case orderParentType.ReportAnalyte:
                            {
                                ReportAnalyte ra;
                                if (Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(r["ReportAnalytePanelId"], 0, false)))
                                {
                                    ra = Analytes.Find(Conversions.ToLong(r["ReportAnalyteId"]), true);
                                }
                                else
                                {
                                    ra = (ReportAnalyte)AnalytePanels.Find(Conversions.ToInteger(r["ReportAnalytePanelId"]), true).Analytes.Find((long)r["ReportAnalyteId"]);
                                }
                                oc = new ReportComment(ra, loadAudit);
                                oc.Load(r);

                                if (!isItemDeleted)
                                {
                                    ra.Comments.List.Add(oc);
                                }
                                else
                                {
                                    ra.Comments.List.AddToArchiveDeleteList(oc);
                                }

                                break;
                            }
                    }

                }
            }

            // Report Flags
            if (datatables[3].Rows.Count > 0)
            {

                foreach (DataRow r in datatables[3].Rows)
                {
                    if (AttachAnalyteAlert(r, _orderAnalytes) == false)
                    {
                        foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
                        {
                            if (AttachAnalyteAlert(r, p.Analytes))
                                break;
                        }
                    }
                }

            }

            // Report Comment Groups
            if (datatables.Length >= 5)
            {
                if (datatables[4].Rows.Count > 0)
                {
                    ReportCommentGroup rcg;
                    foreach (DataRow r in datatables[4].Rows)
                    {
                        rcg = new ReportCommentGroup(this);
                        rcg.Load(r);
                        m_reportCommentGroups.Add(rcg);
                    }

                }
            }

            // Attachments - added 7/12/2015
            if (datatables.Length >= 6)
            {
                if (datatables[5].Rows.Count > 0)
                {
                    Attachment att;
                    foreach (DataRow r in datatables[5].Rows)
                    {
                        ReportAnalyte ra;
                        // Find in Analytes
                        ra = Analytes.Find(Conversions.ToLong(r["ReportAnalyteId"]), true);

                        if (ra is null)
                        {
                            // Find in analytes parts of the panels
                            foreach (ReportAnalytePanel p in AnalytePanels.List)
                            {
                                ra = p.Analytes.Find(Conversions.ToLong(r["ReportAnalyteId"]), true);
                                if (!(ra == null))
                                {
                                    break;
                                }
                            }
                        }

                        if (ra is not null)
                        {
                            att = new Attachment(ra);
                            att.Load(r);
                            ra.AnalyteAttachments.List.Add(att);
                        }
                    }
                }
            }

            if (!string.IsNullOrEmpty(ReferencedOrder.StudyNumber))
            {
                _clinicalTrialTests = ClinicalTrialTests.Fetch(ReferencedOrder.StudyNumber);
            }

        }

        public bool IsBlindedTest(ReportAnalyte analyte)
        {

            if (_clinicalTrialTests is null)
            {
                return false;
            }
            foreach (ClinicalTrialTest ctt in _clinicalTrialTests.List)
            {
                if (ctt.TestIsBlinded && (ctt.TestCode ?? "") == (analyte.Code ?? ""))
                {
                    return true;
                }
            }
            return false;

        }

        private bool AttachAnalyteAlert(DataRow r, ReportAnalytes analytes)
        {
            ReportAlert f;
            foreach (ReportAnalyte a in analytes.List)
            {
                if (Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(a.ID, r["ReportAnalyteId"], false)))
                {
                    f = new ReportAlert(a, LoadAudit);
                    f.Load(r);
                    a.Alerts.List.Add(f);
                    return default;
                }
            }

            return default;

        }

        internal void AddToTestCodeHash(string testCode)
        {

            if (_analytesHash.ContainsKey(testCode) == false)
            {
                _analytesHash.Add(testCode, testCode);
            }

        }

