        public void EvaluateRulesExApply(object triggerObj, string propertyName, int ruleSetId, string[] accessionApplyRules = null)
        {
            try
            {
                bool evalAsTrue = false;
                string code = "";

                if (triggerObj.GetType() == typeof(ReportAnalyte))
                {
                    ReportAnalyte xxx = (ReportAnalyte)triggerObj;
                    LogRules.Debug($"triggerObj code={xxx.Code} value={xxx.ResultValue} tofollowsent={xxx.ToFollowSent}");
                }

                //Get list of rules associated with the class/property that triggered rules evaluation
                RuleManager engine = RuleManager.Fetch(false, ruleSetId);
                RuleEngine.Rule[] rules;
                rules = engine.Rules;
                //List of rules reduced by looking at primary criteria, testcode.
                List<RuleEvaluationHelper> rulesToEval = new List<RuleEvaluationHelper>();
                LogRules.DebugFormat("Rule count {0} for RuleSet Id {1} on Report Id {2}", rules.Length, ruleSetId, this.ID);
                LogRules.DebugFormat("*** Checking rules for accession {0}.", this.AccessionNbr);
                _ruleName = "";

                if (rules.Length > 0)
                {
                    _ruleEvaluationAnalyte = null;

                    foreach (RuleEngine.Rule r in rules)
                    {
                        Debug.WriteLine(r.Name);

                        if (accessionApplyRules.Contains(r.Name))
                        {
                            //Apply only those rule which maches in accessionApplyRules list from parameter
                            //Write an if clause here...
                            LogRules.DebugFormat("--->>>>Applying rule {0}.", r.Name);
                            _ruleName = r.Name;
                            List<string> testcodeList = new List<string>();
                            bool eval = false;

                            if (r.PrimaryCriteria != null)
                            {
                                if (r.PrimaryCriteria.FullName == "Bioreference.LIS.ReportAnalyte.Code")
                                {
                                    foreach (string s in r.PrimaryCriteria.Values)
                                    {
                                        //If triggered from a ReportAnalyte object, then we need to evaluate just for that Analyte
                                        if (triggerObj.GetType() == typeof(ReportAnalyte))
                                        {
                                            if (((ReportAnalyte)triggerObj).Code == s)
                                            {
                                                eval = true;
                                                testcodeList.Add(s);
                                                break;
                                            }
                                        }
                                        else if (AnalyteExists(s))
                                        {
                                            //If triggered from something else, we need to eval for all analytes, if exists.
                                            eval = true;
                                            testcodeList.Add(s); //Add to evaluated test codes
                                        }
                                    }
                                }
                                else
                                {
                                    //Phase 1 - all primary critera will be testcode based.
                                }
                            }

                            if (eval)
                            {
                                rulesToEval.Add(new RuleEvaluationHelper(r, testcodeList));
                                //Log.DebugFormat("Rule to Evaluate: {0}", r.Name)
                            }
                        }
                    }

                    ReportAnalyte analyte;
                    List<RuleEngine.RuleAction> actions = new List<RuleEngine.RuleAction>();

                    foreach (RuleEvaluationHelper r in rulesToEval)
                    {
                        LogRules.DebugFormat("RuleEvaluationHelper {0}", r.Rule.Name);

                        try
                        {
                            foreach (string s in r.TestCodeList)
                            {
                                LogRules.DebugFormat("*** Rules for TestCode: {0} in {1}", s, this.AccessionNbr);
                                code = s;

                                //First check if analyte
                                if (triggerObj.GetType() == typeof(ReportAnalyte) &&
                                    ((ReportAnalyte)triggerObj).Code == s)
                                {
                                    analyte = (ReportAnalyte)triggerObj;
                                }
                                else
                                {
                                    analyte = FindAnalyteForRules(s, true);
                                }

                                if (analyte != null)
                                {
                                    _ruleEvaluationAnalyte = analyte;

                                    foreach (RuleEngine.RuleCriteria c in r.Rule.GetAllCriteria())
                                    {
                                        if (c.ClassName == "Bioreference.LIS.ReportAnalyte")
                                        {
                                            c.SetEvaluateValue(GetPropertyValue(c, analyte));
                                        }
                                        else if (c.ClassName == "Bioreference.LIS.Report")
                                        {
                                            c.SetEvaluateValue(GetPropertyValue(c, this));
                                        }
                                    }
                                }

                                if (r.Rule.Evaluate())
                                {
                                    LogRules.DebugFormat("*** Evaluating rule: {0} in {1}", r.Rule.Name, this.AccessionNbr);

                                    foreach (RuleEngine.RuleAction a in r.Rule.Actions)
                                    {
                                        if (a.ClassName == "Bioreference.LIS.ReportAnalyte")
                                        {
                                            SetPropertyValue(a, analyte);
                                        }
                                        else if (a.ClassName == "Bioreference.LIS.Report")
                                        {
                                            SetPropertyValue(a, this);
                                        }
                                    }

                                    evalAsTrue = true;
                                }
                                else
                                {
                                    //Log.DebugFormat("NOT Evaluating rule: {0} in {1}", r.Rule.Name, Me.AccessionNbr)
                                }
                            }

                            code = "";
                        }
                        catch (Exception ex)
                        {
                            string msg = $"Error evaluating rule: '{r.Rule.Name}', code: {code}: {ex.Message}";
                            Log.Error(msg, ex);
                            throw new Exception(msg, ex);
                        }
                    }
                }

                EvaluateRulesCompleted?.Invoke(this, new EvaluateRulesArg(evalAsTrue));
            }
            catch (Exception ex2)
            {
                Log.Error(ex2.Message, ex2); // redundant logging if this is from the inner try/catch
                throw new Exception($"Error in rule evaluation: {ex2.Message}", ex2);
            }
        }
