        private RuleManager FetchRuleManagerWithRetry(int ruleSetId, int maxRetries = 3, int initialDelayMs = 100)
        {
            RuleManager engine = null;
            int delay = initialDelayMs;
            int attempt = 0;
            Exception lastException = null;

            while (attempt < maxRetries)
            {
                try
                {
                    attempt++;
                    engine = RuleManager.Fetch(false, ruleSetId);

                    if (engine == null)
                    {
                        LogRules.ErrorFormat("Attempt {0}/{1}: RuleManager.Fetch returned Nothing for RuleSet Id {2}", attempt, maxRetries, ruleSetId);
                    }
                    else if (engine.Rules == null)
                    {
                        LogRules.ErrorFormat("Attempt {0}/{1}: RuleManager.Rules is Nothing for RuleSet Id {2}", attempt, maxRetries, ruleSetId);
                    }
                    else if (engine.Rules.Length == 0)
                    {
                        LogRules.ErrorFormat("Attempt {0}/{1}: RuleManager.Fetch returned 0 rules for RuleSet Id {2}", attempt, maxRetries, ruleSetId);
                    }
                    else
                    {
                        LogRules.DebugFormat("Successfully fetched RuleManager with {0} rules on attempt {1} for RuleSet Id {2}", engine.Rules.Length, attempt, ruleSetId);

                        return engine;
                    }

                    if (attempt < maxRetries)
                    {
                        System.Threading.Thread.Sleep(delay);
                        delay *= 2;
                    }
                }
                catch (Exception ex)
                {
                    lastException = ex;

                    LogRules.ErrorFormat("Attempt {0}/{1}: Error fetching RuleManager for RuleSet Id {2}: {3}", attempt, maxRetries, ruleSetId, ex.Message);

                    if (attempt < maxRetries)
                    {
                        System.Threading.Thread.Sleep(delay);
                        delay *= 2;
                    }
                }
            }

            string errorMessage =$"Failed to fetch RuleManager with valid rules for RuleSet Id {ruleSetId} " + $"after {maxRetries} attempts. Accession: {AccessionNbr}";

            LogRules.Error(errorMessage);
            AuditManager.LogCustomObjectAction(this, errorMessage);

            if (lastException != null)
            {
                LogRules.ErrorFormat("Last exception encountered: {0}", lastException.Message);
            }
            return null;
        }
