                                    else if (AnalyteExists(s)) // 'If triggered from something else, we need to eval for all analytes, if exists.
                                    {
                                        eval = true;
                                        testcodeList.Add(s); // Add to evaluated test codes
                                    }
                                }
                            }

                            else
                            {
                                // Phase 1 - all primary critera will be testcode based.
                            }
                        }

                        if (eval)
                        {
                            rulesToEval.Add(new RuleEvaluationHelper(r, testcodeList));
                            // Log.DebugFormat("Rule to Evaluate: {0}", r.Name)
                        }

                    }

                    ReportAnalyte analyte;
                    var actions = new List<RuleAction>();

                    foreach (RuleEvaluationHelper r in rulesToEval)
                    {

                        LogRules.DebugFormat("RuleEvaluationHelper {0}", r.Rule.Name);
                        try
