        private void SetPropertyValue(RuleAction action, object obj)
        {
            IsRuleExecution = true;
            if (!(obj == null))
            {
                var pi = obj.GetType().GetProperty(action.PropertyMethodName);
                if (!(pi == null))
                {
                    pi.SetValue(obj, action.Values[0], default, null, null, null);
                }
                else
                {
                    bool abort = Configuration.LISSettings.GetList("SPMTNPAbortActions").Contains(action.PropertyMethodName, StringComparer.OrdinalIgnoreCase);
                    abort = abort && _ruleEvaluationAnalyte is not null && (_ruleEvaluationAnalyte.SPMStatus == SPMStatusValue.TNP || _ruleEvaluationAnalyte.SPMStatus == SPMStatusValue.ATP);
                    if (_ruleEvaluationAnalyte is not null)
                    {
                        Log.Debug($"Running Rule Action: MethodName={action.PropertyMethodName} analyte code={_ruleEvaluationAnalyte.Code} value={_ruleEvaluationAnalyte.ResultValue} SPMStatus={_ruleEvaluationAnalyte.SPMStatus} abort={abort}");
                    }
                    if (abort)
                        return;
                    var mi = obj.GetType().GetMethod(action.PropertyMethodName);
                    if (!(mi == null))
                    {
                        foreach (string s in action.Values)
                        {
                            Log.Debug($"--> Rule Value {s}");
                            mi.Invoke(obj, default, null, new object[] { s }, null);
                        }
                    }
                }
            }
            IsRuleExecution = false;
        }

        private string GetPropertyValue(RuleCriteria criteria, object obj)
        {
            if (obj != null)
            {

                var pi = obj.GetType().GetProperty(criteria.PropertyName);
                if (pi != null)
                {
                    return pi.GetValue(obj, criteria.Parameters)?.ToString() ?? "";
                }
                var mi = obj.GetType().GetMethod(criteria.PropertyName);
                if (mi != null)
                {

                    var result = mi.Invoke(obj, criteria.Parameters);
                    return result?.ToString() ?? "";
                }
            }
            return "";
        }


        public bool SendAccessionStatusToReporting()
