                    message = string.Format("{0}|{1}||ADD_TEST|{2}", _accessionNbr, testCode, _ruleEvaluationAnalyte.Code);
                else
                    message = string.Format("{0}|{1}||ADD_TEST|", _accessionNbr, testCode);
                var o = new OutboundMessage(_accessionNbr, message, outBoundMessageSendTo.Vertex);
                _outboundMessages.Add(o);
                return true;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

