        private void AddTestMasterCommentCode(string testCode, string commentCode, bool isAutoAdded)
        {

            if (!commentCode.Equals(""))
            {
                var a = FindAnalyte(testCode, true);
                if (!(a == null))
                {

                    var cmts = Common.TestMaster.Comments.Fetch((CommentType)commentType.Canned);
                    var cmt = cmts.FindByVertexCode(commentCode);
                    if (!(cmt == null))
