        public void UpdateResultAndFacility(string testCode, string result, string performingFacility, string accessioningFacility, bool isOnHold, string orderedTestCode, SPMStatusValue spmStatus)
        {
            UpdateResultAndFacility(testCode, result, performingFacility, accessioningFacility, isOnHold, "", Configuration.ToFollowEnabled, (HoldType)Conversions.ToInteger(orderedTestCode), spmStatus: spmStatus);
        }
        // </ITBT-2765>

        // <PRE-ITBT-2765>
        // Public Sub UpdateResultAndFacility(ByVal testCode As String, ByVal result As String, ByVal performingFacility As String, ByVal accessioningFacility As String, ByVal isOnHold As Boolean)
        // UpdateResultAndFacility(testCode, result, performingFacility, accessioningFacility, isOnHold, "", My.Settings.ToFollowEnabled)
        // End Sub
        // </PRE-ITBT-2765>


        // <PRE-ITBT-2765>Public Sub UpdateResultAndFacility(ByVal testCode As String, ByVal result As String, ByVal performingFacility As String, ByVal accessioningFacility As String, ByVal isOnHold As Boolean, ByVal comment As String, Optional ByVal processToFollow As Boolean = False, Optional ByVal holdType As HoldType = HoldType.None)
        public void UpdateResultAndFacility(string testCode, string result, string performingFacility, string accessioningFacility, bool isOnHold, string comment, bool processToFollow = false, HoldType holdType = HoldType.None, string orderedTestCode = "", UpdateIsPresumptive presumptive = null, SPMStatusValue spmStatus = SPMStatusValue.None)   // <ITBT-2765>
        {

            var a = FindAnalyte(testCode, false);
            if (a is not null && string.IsNullOrEmpty(orderedTestCode) | (!string.IsNullOrEmpty(orderedTestCode) && a.OrderingCodes.Contains(orderedTestCode)))
            {

                // 'vcc: 1/27/2016 Skip the update for analyte with TransmitStatus (Reported/SendToReporting/ReadyByReporting/SentToVertex)
                if (!a.HasSampleRequest())
                {
                    if ((int)a.TransmitStatus > 2 && (int)a.TransmitStatus != 10 || a.IsCopiedAnalyte)
                    {
                        return;
                    }
                }

                if (presumptive is not null && presumptive.ProcessUpdate && presumptive.IsPresumptiveHold != a.IsPresumptiveHold)
                {
                    a.IsPresumptiveHold = presumptive.IsPresumptiveHold;
                }
                UpdateResultAnalyte(a, result, performingFacility, accessioningFacility, isOnHold, comment, holdType, orderedTestCode);
                if (!processToFollow || !Configuration.LISSettings.GetList("FacilitiesToFollow").Contains(accessioningFacility))
                {
                    a.ToFollowSent = true;
                }
                // ''''''''''''' Code for test purposes '''''''''''''''''
                else if (Configuration.LISSettings.GetBool("ToFollowJ3333Enabled") && accessioningFacility.Equals("NJ1") && !AccountNumber.Equals("J3333"))
                {
                    a.ToFollowSent = true;
                    // ''''''''''''''''''''''''''''''''''''''''''''''''''''''
                }
            }

            // 'If the panelcode is passed in then update all analytes with facilities and isonhold
            var panel = FindAnalytePanel(testCode);
            if (!(panel == null))
            {
                // NA: 5/17/16 Bypass if already Final
                if (!panel.IsPanelSampleRequested())
                {
                    if ((int)panel.TransmitStatus > 2 && (int)panel.TransmitStatus != 10)
                    {
                        return;
                    }
                }
                bool sampleReceived = panel.CheckIfSampleReceived();
                // NA: if result is TNP/QNS set all analytes to that value and autorelease.
                // panel.SPMStatus = SPMStatusValue.None
                if (SharedFunctions.IsNotPerformedResult(result))
                {
                    panel.SPMStatus = SPMStatusValue.TNP;
                }
                else if (SharedFunctions.IsATP(result))
                {
                    panel.SPMStatus = SPMStatusValue.ATP;
                }
                else
                {
                    panel.SPMStatus = SPMStatusValue.None;
                }

                // 'ITBT-3467 Dim tmpResult As String = IIf(panel.SPMStatus <> ReportAnalytePanel.SPMStatusValue.None, result, "")
                string tmpResult = Conversions.ToString(Interaction.IIf(SharedFunctions.IsNotPerformedResult(result) || SharedFunctions.IsATP(result), result, ""));

                if (!processToFollow || !Configuration.LISSettings.GetList("FacilitiesToFollow").Contains(accessioningFacility))
                {
                    panel.ToFollowSent = true;
                }

                foreach (ReportAnalyte an in panel.Analytes.List)
                {
                    if (presumptive is not null && presumptive.ProcessUpdate && presumptive.IsPresumptiveHold != an.IsPresumptiveHold)
                    {
                        an.IsPresumptiveHold = presumptive.IsPresumptiveHold;
                    }
                    if ((SharedFunctions.IsNotPerformedResult(tmpResult) || SharedFunctions.IsATP(tmpResult)) && an.Analyte.IsRequired)
                    {
                        UpdateResultAnalyte(an, tmpResult, performingFacility, accessioningFacility, isOnHold, comment, holdType, "", orderedTestCode);
                    }
                    else
                    {
                        UpdateResultAnalyte(an, "", performingFacility, accessioningFacility, isOnHold, "", holdType, "", orderedTestCode);
                    }
                    if (!processToFollow || !Configuration.LISSettings.GetList("FacilitiesToFollow").Contains(accessioningFacility))
                    {
                        an.ToFollowSent = true;
                    }
                    // ''''''''''''' Code for test purposes '''''''''''''''''
                    else if (Configuration.LISSettings.GetBool("ToFollowJ3333Enabled") && accessioningFacility.Equals("NJ1") && !AccountNumber.Equals("J3333"))
                    {
                        an.ToFollowSent = true;
                        // ''''''''''''''''''''''''''''''''''''''''''''''''''''''
                    }
                }

                // if the result coming in for this panel is TNP/QNS, we need to also release the Panel.
                if (SharedFunctions.IsNotPerformedResult(tmpResult) || SharedFunctions.IsATP(tmpResult))
                {
                    panel.MarkAsReleased();
                }

                if (sampleReceived)
                {
                    panel.ResetPanel();
                }
            }
            else
            {
                foreach (ReportAnalytePanel p in AnalytePanels.List)
                {
                    a = p.Analytes.FindFirst(testCode);
                    bool sampleReceived = false;
                    if (a is not null && string.IsNullOrEmpty(orderedTestCode) | (!string.IsNullOrEmpty(orderedTestCode) && a.OrderingCodes.Contains(orderedTestCode)))
                    {
                        // 'vcc: 1/27/2016 Skip the update for analyte with TransmitStatus (Reported/SendToReporting/ReadyByReporting/SentToVertex)
                        if (!a.HasSampleRequest())
                        {
                            if ((int)a.TransmitStatus > 2 && (int)a.TransmitStatus != 10)
                            {
                                continue;
                            }
                        }
                        sampleReceived = p.CheckIfSampleReceived();
                        UpdateResultAnalyte(a, result, performingFacility, accessioningFacility, isOnHold, comment, holdType, "", orderedTestCode);  // <ITBT-2765>
                                                                                                                                                     // <PRE-ITBT-2765>UpdateResultAnalyte(a, result, performingFacility, accessioningFacility, isOnHold, comment, holdType)
                        if (!processToFollow || !Configuration.LISSettings.GetList("FacilitiesToFollow").Contains(accessioningFacility))
                        {
                            a.ToFollowSent = true;
                        }
                        // ''''''''''''' Code for test purposes '''''''''''''''''
                        else if (Configuration.LISSettings.GetBool("ToFollowJ3333Enabled") && accessioningFacility.Equals("NJ1") && !AccountNumber.Equals("J3333"))
                        {
                            a.ToFollowSent = true;
                            // ''''''''''''''''''''''''''''''''''''''''''''''''''''''
                        }
                        if (sampleReceived)
                        {
                            p.ResetPanel();
                        }
                    }
                }
            }

        }

        // <PRE-ITBT-2765>Protected Sub UpdateResultAnalyte(ByVal analyte As ReportAnalyte, ByVal result As String, ByVal performingFacility As String, ByVal accessioningFacility As String, ByVal isOnHold As Boolean, ByVal comment As String, Optional ByVal holdType As HoldType = HoldType.None)
        protected void UpdateResultAnalyte(ReportAnalyte analyte, string result, string performingFacility, string accessioningFacility, bool isOnHold, string comment, HoldType holdType = HoldType.None, string orderedTestCode = "", string orderedPanelCode = "")   // <ITBT-2765>
        {

            bool protectCopiedResultStatus = analyte.ID == 0L & analyte.IsCopiedAnalyte & (analyte.ResultStatus == resultStatusType.Final | analyte.ResultStatus == resultStatusType.Corrected);


            bool isStatusFinalOrCorrected = analyte.ResultStatus == resultStatusType.Final || analyte.ResultStatus == resultStatusType.Corrected;

            // TestHoldChanges
            if (!isStatusFinalOrCorrected && holdType == HoldType.TestHold)
            {
                analyte.SetTestHold();
            }
            else if (isOnHold & !protectCopiedResultStatus & !isStatusFinalOrCorrected)
            {
                analyte.ResultStatus = resultStatusType.OnHold;
            }
            else if (analyte.ResultStatus == resultStatusType.OnHold)
            {
                analyte.ResultStatus = (resultStatusType)Conversions.ToInteger(Interaction.IIf(string.IsNullOrEmpty(analyte.ResultValue), resultStatusType.Pending, resultStatusType.Preliminary));
            }
            else if (analyte.IsTestHold && holdType == HoldType.None)
            {
                analyte.RevokeTestHold();
                analyte.ReleaseAfterTestHold();
            }

            if (isStatusFinalOrCorrected && holdType == HoldType.TestHold)
            {
                AuditManager.LogCustomObjectAction(this, $"Analyte code {analyte.Code} in accession {AccessionNbr} has already has been released on date {analyte.ReleaseDate}, so Test Hold Status can not be applied");
            }

            // <PRE-ITBT-2765>
            // If Not String.IsNullOrEmpty(result) Then analyte.ResultValue = result
            // If Not String.IsNullOrEmpty(performingFacility) Then analyte.SetPerformingFacility(performingFacility)
            // If Not String.IsNullOrEmpty(accessioningFacility) Then analyte.SetAccessioningFacility(accessioningFacility)
            // 'if we have a comment, then add it to the result.
            // If Not String.IsNullOrEmpty(comment.Trim()) Then analyte.Comments.AddComment(comment)
            // </PRE-ITBT-2765>
            // <ITBT-2765>
            if (string.IsNullOrEmpty(orderedTestCode) | (!string.IsNullOrEmpty(orderedTestCode) && analyte.OrderingCodes.Contains(orderedTestCode)) | CheckPanelOrderedCode(analyte, orderedPanelCode))
            {
                if (_referencedOrder.SpecimenUpdated)
                {
                    RunOrderCodeAgainstReportForSampleUpdate(orderedTestCode, _referencedOrder);
                    if (_referencedOrder.IsHospitalAccount() && analyte.HasSampleRequest())
                    {
                        analyte.ResetAnalyteToPending();
                    }
                }
                else if (!string.IsNullOrEmpty(result))
                    analyte.ResultValue = result;
                if (!string.IsNullOrEmpty(performingFacility))
                    analyte.SetPerformingFacility(performingFacility);
                if (!string.IsNullOrEmpty(accessioningFacility))
                    analyte.SetAccessioningFacility(accessioningFacility);
                // if we have a comment, then add it to the result.
                if (!string.IsNullOrEmpty(comment.Trim()))
                    analyte.Comments.AddComment(comment);
            }
            // <ITBT-2765>

            // NA: auto-Release TNP/QNS
            if (SharedFunctions.IsNotPerformedResult(analyte.ResultValue))
            {
                analyte.MarkAsReleased();
            }
            // NA: auto-Release ATP
            if (SharedFunctions.IsATP(analyte.ResultValue))
            {
                analyte.MarkAsReleased();
            }
            if (analyte.IsResultStatusChanged())
            {
                AuditManager.LogCustomObjectAction(analyte, "SPM specimen update.");
            }
        }

        private bool CheckPanelOrderedCode(ReportAnalyte analyte, string orderedPanelCode)
        {
            bool returnValue = false;
            if (!string.IsNullOrEmpty(orderedPanelCode) && analyte.Parent is ReportAnalytePanel)
            {
                if (((ReportAnalytePanel)analyte.Parent).ContainsOrderCode(orderedPanelCode))
                {
                    returnValue = true;
                }
            }
            return returnValue;
        }

        private void RunOrderCodeAgainstReportForSampleUpdate(string orderedTestCode, Order _referencedOrder)
        {
            if (!ordredcodelist.Contains(orderedTestCode))
            {
                foreach (ReportAnalyte a in Analytes.List)
                {
                    if (a.OrderingCodes.Contains(orderedTestCode) && _referencedOrder.SpecimenUpdated && _referencedOrder.IsHospitalAccount() && a.HasSampleRequest())
                    {
                        a.ResetAnalyteToPending();
                    }
                }

                foreach (ReportAnalytePanel p in _orderAnalytePanels.List)
                {
                    if (p.OrderingCodes.Contains(orderedTestCode))
                    {
                        foreach (ReportAnalyte a in p.Analytes.List)
                        {
                            if (_referencedOrder.SpecimenUpdated && _referencedOrder.IsHospitalAccount() && a.HasSampleRequest())
                            {
                                a.ResetAnalyteToPending();
                            }
                        }
                    }
                }
                ordredcodelist.Add(orderedTestCode);
            }
        }

