        /// <summary>
        /// Created specifically for Rules engine.
        /// </summary>
        /// <remarks></remarks>
        public void MarkAsReleased(string testCode)
        {

            var a = FindAnalyte(testCode, true);
            if (!(a == null))
            {
                if (!string.IsNullOrEmpty(a.ResultValue))
                {
                    a.SetFinalOrCorrected();
                    a.MarkAsReleased();
                }
            }

            var p = FindAnalytePanel(testCode);
            if (!(p == null))
            {
                foreach (ReportAnalyte ra in p.Analytes.List)
                {
                    ra.SetFinalOrCorrected();
                    ra.MarkAsReleased();
                }
            }

        }

        /// <summary>
        /// Created specifically for Rules engine.
        /// </summary>
        /// <remarks></remarks>
        public void MarkAsPreliminaryReleased(string testCode)
        {

            var a = FindAnalyte(testCode, true);
            if (!(a == null))
            {
                if (!string.IsNullOrEmpty(a.ResultValue))
                {
                    a.MarkAsPreliminaryReleased();
                }
            }

            var p = FindAnalytePanel(testCode);
            if (!(p == null))
            {
                p.MarkAsPreliminaryReleased();
            }

        }

        private void SetStatus(ReportAnalyte analyte, resultStatusType status)
        {
            if (analyte is not null)
            {
                SetStatusBeforeRule(analyte);
                analyte.ResultStatus = status;
                if (status != resultStatusType.Final)
                {
                    analyte.SetTransmitStatus(transmitStatusType.PendingRelease);
                }
            }
        }

        private void SetStatus(string testCodes, resultStatusType status)
        {

            string[] tc = testCodes.Split(',');

            foreach (string testCode in tc)
            {

                var a = FindAnalyte(testCode, true);
                if (!(a == null))
                {
                    SetStatusBeforeRule(a);
                    a.ResultStatus = status;
                    if (status != resultStatusType.Final)
                    {
                        a.SetTransmitStatus(transmitStatusType.PendingRelease);
                    }
                }

                var p = FindAnalytePanel(testCode);
                if (!(p == null))
                {
                    foreach (ReportAnalyte ra in p.Analytes.List)
                    {
                        SetStatusBeforeRule(ra);
                        ra.ResultStatus = status;
                        if (status != resultStatusType.Final)
                        {
                            ra.SetTransmitStatus(transmitStatusType.PendingRelease);
                        }
                    }
                }

            }

        }

        private void SetStatusBeforeRule(ReportAnalyte analyte)
        {
            if (!analyte.IsRuleResultStatusSet)
            {
                analyte.IsRuleResultStatusSet = true;
                analyte.SetCorrectedStatusFlagForRules(analyte.ResultStatus);
            }
        }

        #endregion

        public class ReportStatus
        {
            public DateTime DateReported;
            public reportStatusType AccessionStatus;
        }

        public class UpdateIsPresumptive
        {
            public bool ProcessUpdate;
            public bool IsPresumptiveHold;
        }

        private class FourKCalculationException : Exception
        {

            public FourKCalculationException(string msg) : base(msg)
            {
            }

        }

    }
